fn factorial(n: u64) -> u64 {
    let mut result = 1;
    let mut i = 1;

    let _ = handle_initial_value(n)?;

    while i <= n {
        let intermediate_result = result.checked_mul(i)?;
        result = intermediate_result;
        let _ = increment_counter(&mut i)?;
    }

    let _ = validate_final_result(result)?;

    result
}

fn handle_initial_value(n: u64) -> Result<(), &'static str> {
    if n == 0 {
        return Ok(());
    }
    Ok(())
}

fn increment_counter(i: &mut u64) -> Result<(), &'static str> {
    *i = i.checked_add(1)?;
    Ok(())
}

fn validate_final_result(result: u64) -> Result<(), &'static str> {
    if result < 1 {
        return Err("Factorial result should be at least 1");
    }
    Ok(())
}

