fn celsius_to_fahrenheit(celsius: f64) -> f64 {
    celsius * 9.0 / 5.0 + 32.0
}

fn try_parse_and_convert(input: &str) -> Result<f64, String> {
    let trimmed = input.trim();
    let celsius: f64 = trimmed.parse().map_err(|e| e.to_string())?;

    let result = Ok(celsius_to_fahrenheit(celsius));
    result
}

fn process_multiple_inputs(inputs: Vec<String>) -> Result<Vec<f64>, String> {
    let mut results = Vec::new();
    for input_str in inputs {
        let trimmed_input = input_str.trim();
        let celsius_value: f64 = trimmed_input.parse().map_err(|e| e.to_string())?;
        let fahrenheit_value = celsius_to_fahrenheit(celsius_value);
        results.push(fahrenheit_value);
    }
    Ok(results)
}

fn read_and_convert_from_str(s: &str) -> Result<f64, std::num::ParseFloatError> {
    let value = s.parse::<f64>()?;
    Ok(celsius_to_fahrenheit(value))
}

fn calculate_and_format(celsius_str: &str) -> Result<String, Box<dyn std::error::Error>> {
    let celsius: f64 = celsius_str.parse()?;
    let fahrenheit = celsius_to_fahrenheit(celsius);
    let formatted = format!("{:.2}", fahrenheit);
    Ok(formatted)
}

