fn trim_whitespace(s: &str) -> String {
    let mut chars = s.chars();
    let mut start_index = 0;
    let mut end_index = s.len();

    while let Some(c) = chars.next() {
        if !c.is_whitespace() {
            break;
        }
        start_index += c.len_utf8();
    }

    let mut rev_chars = s.chars().rev();
    while let Some(c) = rev_chars.next() {
        if !c.is_whitespace() {
            break;
        }
        end_index -= c.len_utf8();
    }

    if start_index >= end_index {
        return String::new();
    }

    s[start_index..end_index].to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_string() -> Result<(), String> {
        let result = trim_whitespace("");
        assert_eq!(result, "");
        Ok(())
    }

    #[test]
    fn test_no_whitespace() -> Result<(), String> {
        let result = trim_whitespace("hello");
        assert_eq!(result, "hello");
        Ok(())
