fn count_word_occurrences(text: &str, word: &str) -> usize {
    let lower_text = text.to_lowercase();
    let lower_word = word.to_lowercase();
    let mut count = 0;
    let mut start_index = 0;

    while let Some(index) = lower_text[start_index..].find(&lower_word) {
        count += 1;
        start_index += index + lower_word.len();
    }
    count
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let result1 = count_word_occurrences("Hello world, hello Rust", "hello");
    println!("Count 1: {}", result1);

    let result2 = count_word_occurrences("The quick brown fox", "dog");
    println!("Count 2: {}", result2);

    let result3 = count_word_occurrences("Rust is fun. rust is great.", "Rust");
    println!("Count 3: {}", result3);

    let input_file_path = "input.txt";
    std::fs::write(input_file_path, "One two three one four one.")?;
    let file_content = std::fs::read_to_string(input_file_path)?;
    let file_word_count = count_word_occurrences(&file_content, "one");
    println!("File word 'one' count: {}", file_word_count);

    let non_existent_file = "non_existent.txt";
    let _ = std::fs::read_to_string(non_existent_file).map_err(|e| {
        eprintln!("Error reading non-existent file: {}", e);
        e
    })?;

    let another_file_path = "another_input.txt";
    let mut file = std::fs::File::create(another_file_path)?;
    use std::io::Write;
    file.write_all(b"Test test test")?;
    let another_content = std::fs::read_to_string(another_file_path)?;
    let another_count = count_word_occurrences(&another_content, "test");
    println!("Another file 'test' count: {}", another_count);

    let non_utf8_file = "non_utf8.txt";
    let mut non_utf8_f = std::fs::File::create(non_utf8_file)?;
    non_utf8_f.write_all(&[0xc3, 0x28])?; // Invalid UTF-8 sequence
    let _ = std::fs::read_to_string(non_utf8_file).map_err(|e| {
        eprintln!("Error reading non-UTF-8 file: {}", e);
        e
    })?;

    Ok(())
}

