use std::collections::HashMap;

fn are_anagrams(s1: &str, s2: &str) -> bool {
    let map1 = s1.chars()
        .filter_map(|c| c.to_lowercase().next())
        .filter(|c| c.is_alphabetic())
        .try_fold(HashMap::new(), |mut acc, c| {
            *acc.entry(c).or_insert(0) += 1;
            Ok::<_, !>(acc)
        })
        .ok()?;

    let map2 = s2.chars()
        .filter_map(|c| c.to_lowercase().next())
        .filter(|c| c.is_alphabetic())
        .try_fold(HashMap::new(), |mut acc, c| {
            *acc.entry(c).or_insert(0) += 1;
            Ok::<_, !>(acc)
        })
        .ok()?;

    if map1.len() != map2.len() {
        return false;
    }

    for (key, val) in map1 {
        if map2.get(&key)? != Some(&val) {
            return false;
        }
    }

    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_anagrams_basic() {
        assert!(are_anagrams("listen", "silent"));
    }

    #[test]
    fn test_anagrams_case_insensitive() {
        assert!(are_anagrams("LISTEN", "silent"));
    }

    #[test]
    fn test_anagrams_with_spaces() {
        assert!(are_anagrams("A gentleman", "Elegant man"));
    }

    #[test]
    fn test_not_anagrams_different_chars() {
        assert!(!are_anagrams("hello", "world"));
    }

    #[test]
    fn test_not_anagrams_different_counts() {
        assert!(!are_anagrams("aabbc", "abc"));
    }

    #[test]
    fn test_empty_strings() {
        assert!(are_anagrams("", ""));
    }

    #[test]
    fn test_one_empty_string() {
        assert!(!are_anagrams("a", ""));
        assert!(!are_anagrams("", "b"));
    }

    #[test]
    fn test_punctuation() {
        assert!(are_anagrams("Madam Curie", "Radium came"));
    }

    #[test]
    fn test_numbers_ignored() {
        assert!(are_anagrams("a1b2c", "cba"));
    }
}

