use std::io::{self, Write};

fn filter_long_words(words: &[&str], min_length: usize) -> io::Result<Vec<String>> {
    let mut long_words = Vec::new();
    let stdout = io::stdout();
    let mut handle = stdout.lock();

    for word in words {
        handle.write_all(format!("Checking word: {}\n", word).as_bytes())?;
        if word.len() > min_length {
            long_words.push(word.to_string());
        }
    }

    let message = format!("Finished filtering. Found {} long words.\n", long_words.len());
    handle.write_all(message.as_bytes())?;
    handle.flush()?;

    Ok(long_words)
}

fn main() -> io::Result<()> {
    let words1 = &["a", "apple", "banana", "grapefruit"];
    let result1 = filter_long_words(words1, 3)?;
    println!("Result 1: {:?}", result1);

    let words2 = &["cat", "dog", "bird"];
    let result2 = filter_long_words(words2, 5)?;
