fn parse_radius(s: &str) -> Result<f64, std::num::ParseFloatError> {
    let radius = s.parse::<f64>()?;
    Ok(radius)
}

fn calculate_area_from_string(radius_str: &str) -> Result<f64, Box<dyn std::error::Error>> {
    let radius = parse_radius(radius_str)?;
    if radius < 0.0 {
        return Err("Radius cannot be negative".into());
    }
    let area = std::f64::consts::PI * radius * radius;
    Ok(area)
}

fn get_input_line() -> Result<String, std::io::Error> {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input)?;
    Ok(input.trim().to_string())
}

fn circle_area_interactive() -> Result<f64, Box<dyn std::error::Error>> {
    println!("Enter the radius of the circle:");
    let input_line = get_input_line()?;
    let area = calculate_area_from_string(&input_line)?;
    Ok(area)
}

fn circle_area(radius: f64) -> f64 {
    std::f64::consts::PI * radius * radius
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let area1 = circle_area(1.0);
    println!("Area for radius 1.0: {}", area1);

    let area2 = circle_area(2.0);
    println!("Area for radius 2.0: {}", area2);

    let interactive_area = circle_area_interactive()?;
    println!("Calculated area from input: {}", interactive_area);

    let explicit_string_area = calculate_area_from_string("3.0")?;
    println!("Area from string '3.0': {}", explicit_string_area);

    let explicit_string_area_fail = calculate_area_from_string("-1.0");
    if let Err(e) = explicit_string_area_fail {
        println!("Error for string '-1.0': {}", e);
    }

    let parse_test_ok = parse_radius("4.0")?;
    println!("Parsed radius '4.0': {}", parse_test_ok);

    let parse_test_fail = parse_radius("not_a_number");
    if let Err(e) = parse_test_fail {
        println!("Error parsing 'not_a_number': {}", e);
    }

    Ok(())
}

