use std::collections::HashMap;

fn update_inventory(
    current: Vec<(&str, u32)>,
    changes: Vec<(&str, i32)>,
) -> Result<Vec<(String, u32)>, String> {
    let mut inventory: HashMap<String, u32> = HashMap::new();

    for (item, qty) in current {
        inventory.insert(item.to_string(), qty);
    }

    for (item, change) in changes {
        let current_qty = inventory.get(item).cloned().unwrap_or(0);
        let new_qty = if change.is_positive() {
            current_qty.checked_add(change as u32).ok_or_else(|| "Overflow adding item".to_string())?
        } else {
            current_qty.checked_sub(change.abs() as u32).ok_or_else(|| "Underflow removing item".to_string())?
        };
        inventory.insert(item.to_string(), new_qty);
    }

    let mut result: Vec<(String, u32)> = inventory.into_iter().collect();
    result.sort_by(|a, b| a.0.cmp(&b.0)); // Optional: sort for consistent output

    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_update_inventory_add_and_new() -> Result<(), String> {
        let current = vec![("apple", 5)];
        let changes = vec![("apple", 2), ("banana", 3)];
        let expected = vec![("apple".to_string(), 7), ("banana".to_string(), 3)];
        let result = update_inventory(current, changes)?;
        assert_eq!(result, expected);
        Ok(())
    }

    #[test]
    fn test_update_inventory_remove() -> Result<(), String> {
        let current = vec![("item", 10)];
        let changes = vec![("item", -5)];
        let expected = vec![("item".to_string(), 5)];
        let result = update_inventory(current, changes)?;
        assert_eq!(result, expected);
        Ok(())
    }

    #[test]
    fn test_update_inventory_complex() -> Result<(), String> {
        let current = vec![("A", 10), ("B", 20)];
        let changes = vec![("A", -3), ("C", 5), ("B", 10)];
        let expected = vec![("A".to_string(), 7), ("B".to_string(), 30), ("C".to_string(), 5)];
        let result = update_inventory(current, changes)?;
        assert_eq!(result, expected);
        Ok(())
    }

    #[test]
    fn test_update_inventory_overflow() {
        let current = vec![("apple", u32::MAX)];
        let changes = vec![("apple", 1)];
        let result = update_inventory(current, changes);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Overflow adding item");
    }

    #[test]
    fn test_update_inventory_underflow() {
        let current = vec![("apple", 5)];
        let changes = vec![("apple", -6)];
        let result = update_inventory(current, changes);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Underflow removing item");
    }
}

