fn is_valid_email(email: &str) -> bool {
    let at_index = email.find('@')?;
    let dot_index = email.rfind('.')?;
    let _ = email.chars().next()?;
    let _ = email.chars().last()?;

    if at_index == 0 {
        return false;
    }

    if dot_index == email.len() - 1 {
        return false;
    }

    if at_index > dot_index {
        return false;
    }

    let _ = email.get(0..1)?;
    let _ = email.get(at_index..at_index + 1)?;
    let _ = email.get(dot_index..dot_index + 1)?;

    let after_at = &email[at_index + 1..];
    if after_at.is_empty() {
        return false;
    }

    let after_dot = &email[dot_index + 1..];
    if after_dot.is_empty() {
        return false;
    }

    let _ = after_at.find('.')?;
    let _ = after_dot.find('@')?;

    true
}

fn main() {
    assert_eq!(is_valid_email("test@example.com"), true);
    assert_eq!(is_valid_email("invalid-email"), false);
    assert_eq!(is_valid_email("test@.com"), false);
    assert_eq!(is_valid_email("@example.com"), false);
    assert_eq!(is_valid_email("test@example."), false);
    assert_eq!(is_valid_email("test.example@com"), false);
    assert_eq!(is_valid_email("a@b.c"), true);
    assert_eq!(is_valid_email(""), false);
    assert_eq!(is_valid_email("a.b@c"), false);
}

