use std::{error::Error, fs::File, io::{self, Write}};

fn roll_die() -> u8 {
    thread_rng().gen_range(1..=6)
}

fn simulate_rolls(num_rolls: usize) -> Result<(), Box<dyn Error>> {
    let mut file = File::create("dice_rolls.txt")?;
    let mut total_sum: u64 = 0;

    for i in 0..num_rolls {
        let roll = roll_die();
        let roll_str = roll.to_string();
        file.write_all(roll_str.as_bytes())?;
        file.write_all(b"\n")?;
        total_sum += roll as u64;
        if i % 100 == 0 {
            io::stdout().write_all(b".")?;
            io::stdout().flush()?;
        }
    }

    io::stdout().write_all(b"\n")?;
    let avg = total_sum as f64 / num_rolls as f64;
    let avg_str = format!("Average roll: {:.2}\n", avg);
    file.write_all(avg_str.as_bytes())?;

    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let num_rolls_str = "1000";
    let num_rolls: usize = num_rolls_str.parse()?;

    simulate_rolls(num_rolls)?;

    let mut contents = String::new();
    let mut file = File::open("dice_rolls.txt")?;
    io::Read::read_to_string(&mut file, &mut contents)?;

    println!("File content preview (first 5 lines):\n{}", contents.lines().take(5).collect::<Vec<&str>>().join("\n"));

    Ok(())
}

