}

fn simulate_rolls(num_rolls: usize) -> Result<(), Box<dyn Error>> {
    let mut file = match File::create("dice_rolls.txt") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let mut total_sum: u64 = 0;

    for i in 0..num_rolls {
        let roll = roll_die();
        let roll_str = roll.to_string();
        match file.write_all(roll_str.as_bytes()) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        match file.write_all(b"\n") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        total_sum += roll as u64;
        if i % 100 == 0 {
            match io::stdout().write_all(b".") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };
            match io::stdout().flush() {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };
        }
    }

    match io::stdout().write_all(b"\n") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let avg = total_sum as f64 / num_rolls as f64;
