use std::collections::HashMap;

fn char_frequencies(s: &str) -> HashMap<char, usize> {
    let mut frequencies: HashMap<char, usize> = HashMap::new();
    for c in s.chars() {
        let lower_c = c.to_ascii_lowercase();
        *frequencies.entry(lower_c).or_insert(0) += 1;
    }
    frequencies
}

