fn _is_valid_date_format_impl(s: &str) -> Result<bool, ()> {
    if s.len() != 10 {
        return Ok(false);
    }

    let mut chars = s.chars();

    chars.next()?.to_digit(10).ok_or(())?;
    chars.next()?.to_digit(10).ok_or(())?;
    chars.next()?.to_digit(10).ok_or(())?;
    chars.next()?.to_digit(10).ok_or(())?;

    if chars.next()? != '-' {
        return Ok(false);
    }

    chars.next()?.to_digit(10).ok_or(())?;
    chars.next()?.to_digit(10).ok_or(())?;

    if chars.next()? != '-' {
        return Ok(false);
    }

    chars.next()?.to_digit(10).ok_or(())?;
    chars.next()?.to_digit(10).ok_or(())?;

    Ok(chars.next().is_none())
}

