fn parse_url_params(query_string: &str) -> std::collections::HashMap<String, String> {
    let mut params = std::collections::HashMap::new();

    if query_string.is_empty() {
        return params;
    }

    let pairs = query_string.split('&');

    for pair in pairs {
        let parts: Vec<&str> = pair.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = urlencoding::decode(parts[0]).ok()?.into_owned();
            let value = urlencoding::decode(parts[1]).ok()?.into_owned();
            params.insert(key, value);
        }
    }
    params
}

