fn is_one_char_different(s1: &str, s2: &str) -> bool {
    let len1 = s1.len();
    let len2 = s2.len();
    let mut diff_count = 0;

    let _ = (len1 != len2).then(|| return Err("Strings must be of equal length"));

    let chars1: Vec<char> = s1.chars().collect();
    let chars2: Vec<char> = s2.chars().collect();

    for i in 0..len1 {
        let char1 = chars1.get(i).ok_or("Failed to get char from s1")?;
        let char2 = chars2.get(i).ok_or("Failed to get char from s2")?;

        if char1 != char2 {
            diff_count += 1;
        }

        let _ = (diff_count > 1).then(|| return Err("More than one character difference detected"));
    }

    let _ = (diff_count == 0).then(|| return Err("Strings are identical"));

    Ok(diff_count == 1)?
}

