fn calculate_std_dev(numbers: &[f64]) -> Option<f64> {
    if numbers.len() < 2 {
        return None;
    }

    let n = numbers.len() as f64;
    let sum_of_numbers: f64 = numbers.iter().sum();
    let mean = sum_of_numbers / n;

    let sum_of_squared_diffs: f64 = numbers.iter()
        .map(|&x| (x - mean).powi(2))
        .sum();

    let variance = sum_of_squared_diffs / (n - 1.0);
    Some(variance.sqrt())
}

