fn roman_to_int(roman: &str) -> Result<u32, &'static str> {
    let mut total = 0;
    let mut prev_value = 0;

    for c in roman.chars().rev() {
        let current_value = match c {
            'I' => 1,
            'V' => 5,
            'X' => 10,
            'L' => 50,
            'C' => 100,
            _ => return Err("Invalid Roman numeral character"),
        };

        if current_value < prev_value {
            total = total.checked_sub(current_value).ok_or("Integer underflow")?;
        } else {
            total = total.checked_add(current_value).ok_or("Integer overflow")?;
        }
        prev_value = current_value;
    }
    Ok(total)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_simple_numerals() -> Result<(), &'static str> {
        assert_eq!(roman_to_int("I")?, 1);
