        assert_eq!(roman_to_int("X")?, 10);
        assert_eq!(roman_to_int("L")?, 50);
        assert_eq!(roman_to_int("C")?, 100);
        Ok(())
    }

    #[test]
    fn test_subtractive_numerals() -> Result<(), &'static str> {
        assert_eq!(roman_to_int("IV")?, 4);
        assert_eq!(roman_to_int("IX")?, 9);
        assert_eq!(roman_to_int("XL")?, 40);
        assert_eq!(roman_to_int("XC")?, 90);
