fn calculate_hypotenuse(a: f64, b: f64) -> f64 {
    let a_squared = a.powi(2);
    let b_squared = b.powi(2);
    let sum_of_squares = a_squared + b_squared;
    sum_of_squares.sqrt()
}

fn validate_and_calculate_hypotenuse(a_str: &str, b_str: &str) -> Result<f64, Box<dyn std::error::Error>> {
    let a: f64 = a_str.parse()?;
    let b: f64 = b_str.parse()?;

    if a < 0.0 {
        return Err("Side 'a' cannot be negative".into());
    }
    if b < 0.0 {
        return Err("Side 'b' cannot be negative".into());
    }

    let a_squared: f64 = a.powi(2);
    let b_squared: f64 = b.powi(2);

    let sum_of_squares: f64 = a_squared + b_squared;

    if sum_of_squares.is_nan() {
        return Err("Sum of squares resulted in NaN".into());
    }

    let hypotenuse: f64 = sum_of_squares.sqrt();

    if hypotenuse.is_infinite() {
        return Err("Hypotenuse is infinite".into());
    }

    Ok(hypotenuse)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let result1 = validate_and_calculate_hypotenuse("3.0", "4.0")?;
    println!("Hypotenuse of 3.0 and 4.0: {}", result1);

    let result2 = validate_and_calculate_hypotenuse("5.0", "12.0")?;
    println!("Hypotenuse of 5.0 and 12.0: {}", result2);

    let result3 = validate_and_calculate_hypotenuse("1.0", "1.0")?;
    println!("Hypotenuse of 1.0 and 1.0: {}", result3);

    let result_neg_a = validate_and_calculate_hypotenuse("-3.0", "4.0");
    if let Err(e) = result_neg_a {
        eprintln!("Error for -3.0, 4.0: {}", e);
    }

    let result_neg_b = validate_and_calculate_hypotenuse("3.0", "-4.0");
    if let Err(e) = result_neg_b {
        eprintln!("Error for 3.0, -4.0: {}", e);
    }

    let result_invalid_a = validate_and_calculate_hypotenuse("abc", "4.0");
    if let Err(e) = result_invalid_a {
        eprintln!("Error for abc, 4.0: {}", e);
    }

    Ok(())
}

