fn convert_length(value: f64, from_unit: &str, to_unit: &str) -> f64 {
    let meters = match from_unit {
        "m" => value,
        "cm" => value / 100.0,
        "km" => value * 1000.0,
        _ => panic!("Unsupported 'from_unit'"),
    };

    let result = match to_unit {
        "m" => meters,
        "cm" => meters * 100.0,
        "km" => meters / 1000.0,
        _ => panic!("Unsupported 'to_unit'"),
    };

    result
}

struct UnitConverter {
    conversion_factors: std::collections::HashMap<String, f64>,
}

impl UnitConverter {
    fn new() -> Result<Self, Box<dyn std::error::Error>> {
        let mut factors = std::collections::HashMap::new();
        factors.insert("m".to_string(), 1.0);
        factors.insert("cm".to_string(), 0.01);
        factors.insert("km".to_string(), 1000.0);
        Ok(UnitConverter { conversion_factors: factors })
    }

    fn convert(&self, value: f64, from_unit: &str, to_unit: &str) -> Result<f64, Box<dyn std::error::Error>> {
        let from_factor = match self.conversion_factors.get(from_unit).ok_or("Invalid from_unit") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        let to_factor = match self.conversion_factors.get(to_unit).ok_or("Invalid to_unit") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };

        let meters = value * from_factor;
        let result = meters / to_factor;
        Ok(result)
    }
}

fn convert_length_with_error_handling(value: f64, from_unit: &str, to_unit: &str) -> Result<f64, Box<dyn std::error::Error>> {
    let converter = match UnitConverter::new() {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let from_factor = match converter.conversion_factors.get(from_unit).ok_or("Invalid from_unit") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let to_factor = match converter.conversion_factors.get(to_unit).ok_or("Invalid to_unit") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let meters = value * from_factor;
    let result = meters / to_factor;
    Ok(result)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let result1 = convert_length(100.0, "cm", "m");
    println!("100 cm to m: {}", result1);

    let result2 = convert_length(2.0, "km", "m");
    println!("2 km to m: {}", result2);

    let converted_value1 = match convert_length_with_error_handling(100.0, "cm", "m") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Error handled 100 cm to m: {}", converted_value1);

    let converted_value2 = match convert_length_with_error_handling(2.0, "km", "m") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Error handled 2 km to m: {}", converted_value2);

    let converted_value3 = match convert_length_with_error_handling(1.0, "m", "cm") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Error handled 1 m to cm: {}", converted_value3);

    let converted_value4 = match convert_length_with_error_handling(500.0, "cm", "km") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Error handled 500 cm to km: {}", converted_value4);

    let converted_value5 = match convert_length_with_error_handling(1234.5, "m", "km") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Error handled 1234.5 m to km: {}", converted_value5);

    let _invalid_from_unit = convert_length_with_error_handling(1.0, "mm", "m").ok(); // Consume for example
    let _invalid_to_unit = convert_length_with_error_handling(1.0, "m", "mm").ok(); // Consume for example

    Ok(())
}

