fn simple_linear_regression(x: &[f64], y: &[f64]) -> Option<(f64, f64)> {
    let n = x.len();
    if n < 2 || n != y.len() {
        return None;
    }

    let sum_x = x.iter().sum::<f64>();
    let sum_y = y.iter().sum::<f64>();
    let sum_xy: f64 = x.iter().zip(y.iter()).map(|(&xi, &yi)| xi * yi).sum()?; // ? on sum
    let sum_x_sq: f64 = x.iter().map(|&xi| xi * xi).sum()?; // ? on sum

    let n_f64 = n as f64;
    let numerator = n_f64 * sum_xy - sum_x * sum_y;
    let denominator = n_f64 * sum_x_sq - sum_x * sum_x;

    if denominator.abs() < f64::EPSILON {
        return None; // Vertical line or all x values are the same
    }

    let m = numerator / denominator;
    let b = (sum_y - m * sum_x) / n_f64;

    Some((m, b))
}

