        assert_eq!(result, None);
        Some(())
    }

    #[test]
    fn test_perfect_fit() -> Option<()> {
        let result = simple_linear_regression(&[1.0, 2.0, 3.0], &[2.0, 4.0, 6.0])?;
        assert_eq!(result.0, 2.0);
        assert_eq!(result.1, 0.0);
        Some(())
    }

