fn shuffle_deck(deck: &mut Vec<String>) -> Result<(), Box<dyn std::error::Error>> {
    let mut rng = rand::thread_rng();
    deck.shuffle(&mut rng);
    Ok(())
}

fn read_cards_from_file(path: &str) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let content = std::fs::read_to_string(path)?;
    let cards = content.lines().map(String::from).collect();
    Ok(cards)
}

fn write_shuffled_deck_to_file(path: &str, deck: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = std::fs::File::create(path)?;
    for card in deck {
        writeln!(file, "{}", card)?;
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let input_path = "cards.txt";
    let output_path = "shuffled_cards.txt";

    std::fs::write(input_path, "Ace\nKing\nQueen\nJack")?;

    let mut deck = read_cards_from_file(input_path)?;
    shuffle_deck(&mut deck)?;
    write_shuffled_deck_to_file(output_path, &deck)?;

    println!("Shuffled deck written to {}", output_path);
    let final_content = std::fs::read_to_string(output_path)?;
    println!("Content: \n{}", final_content);

    Ok(())
}

