fn write_shuffled_deck_to_file(path: &str, deck: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let mut file = match std::fs::File::create(path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    for card in deck {
        match writeln!(file, "{}", card) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let input_path = "cards.txt";
    let output_path = "shuffled_cards.txt";

    match std::fs::write(input_path, "Ace\nKing\nQueen\nJack") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let mut deck = match read_cards_from_file(input_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    match shuffle_deck(&mut deck) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    match write_shuffled_deck_to_file(output_path, &deck) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    println!("Shuffled deck written to {}", output_path);
    let final_content = match std::fs::read_to_string(output_path) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Content: \n{}", final_content);

    Ok(())
}

