use std::io::{self, Write};

fn allocate_resources(capacity: u32, resource_needs: Vec<u32>) -> io::Result<Vec<u32>> {
    let mut allocated_resources = Vec::new();
    let mut current_capacity = capacity;

    for &need in resource_needs.iter() {
        if need <= current_capacity {
            current_capacity -= need;
            allocated_resources.push(need);
        }
    }

    Ok(allocated_resources)
}

fn main() -> io::Result<()> {
    let mut input_capacity = String::new();
    print!("Enter total capacity: ");
    io::stdout().flush()?; // Propagate error
    io::stdin().read_line(&mut input_capacity)?; // Propagate error
    let capacity: u32 = input_capacity.trim().parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?; // Propagate error

    let mut input_needs = String::new();
    print!("Enter resource needs (space-separated): ");
    io::stdout().flush()?; // Propagate error
    io::stdin().read_line(&mut input_needs)?; // Propagate error

    let resource_needs: Vec<u32> = input_needs
        .trim()
        .split_whitespace()
        .map(|s| s.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e)))
        .collect::<Result<Vec<u32>, io::Error>>()?; // Propagate error

    let allocated = allocate_resources(capacity, resource_needs)?; // Propagate error
    println!("Allocated resources: {:?}", allocated);

    Ok(())
}

