use std::num::ParseIntError;

fn binary_to_decimal(binary_str: &str) -> Result<u32, ParseIntError> {
    let mut decimal_value: u32 = 0;
    let mut power: u32 = 0;

    for bit_char in binary_str.chars().rev() {
        let bit = bit_char.to_string().parse::<u32>()?;
        if bit != 0 && bit != 1 {
            // This case should ideally not happen if input is guaranteed '0's and '1's
            // but we'll leave it as an example of error propagation.
            // A more idiomatic error would be to return a custom error type.
            return "Invalid bit character".parse::<u32>(); // Demonstrates ? for error
        }
        decimal_value += bit * 2u32.pow(power);
        power += 1;
    }

    Ok(decimal_value)
}

fn main() -> Result<(), ParseIntError> {
    let num1 = binary_to_decimal("101")?;
    println!("'101' in decimal is: {}", num1);

    let num2 = binary_to_decimal("1111")?;
    println!("'1111' in decimal is: {}", num2);

    let num3 = binary_to_decimal("0")?;
    println!("'0' in decimal is: {}", num3);

    let num4 = binary_to_decimal("1")?;
    println!("'1' in decimal is: {}", num4);

    let num5_str = "10000000000000000000000000000000"; // 2^31
    let num5 = binary_to_decimal(num5_str)?;
    println!("'{}' in decimal is: {}", num5_str, num5);

    let num6_str = "11111111111111111111111111111111"; // u32::MAX
    let num6 = binary_to_decimal(num6_str)?;
    println!("'{}' in decimal is: {}", num6_str, num6);

    let _invalid_parse = "abc".parse::<u32>()?; // Another ? example
    let _another_invalid = "2".parse::<u32>()?; // Yet another ?

    Ok(())
}

