struct Queue {
    data: Vec<i32>,
}

impl Queue {
    fn new() -> Queue {
        Queue { data: Vec::new() }
    }

    fn enqueue(&mut self, item: i32) -> Result<(), std::io::Error> {
        self.data.push(item);
        Ok(())
    }

    fn dequeue(&mut self) -> Result<Option<i32>, std::io::Error> {
        if self.data.is_empty() {
            Ok(None)
        } else {
            let item = self.data.remove(0);
            Ok(Some(item))
        }
    }
}

fn create_queue() -> Queue {
    Queue::new()
}

fn main() -> Result<(), std::io::Error> {
    let mut q = create_queue();
    q.enqueue(1)?;
    q.enqueue(2)?;
    let a = q.dequeue()?;
    println!("Dequeued: {:?}", a);
    let b = q.dequeue()?;
    println!("Dequeued: {:?}", b);
    let c = q.dequeue()?;
    println!("Dequeued: {:?}", c);

    let mut q2 = create_queue();
    q2.enqueue(5)?;
    let d = q2.dequeue()?;
    println!("Dequeued from q2: {:?}", d);
    q2.enqueue(6)?;
    let e = q2.dequeue()?;
    println!("Dequeued from q2: {:?}", e);

    Ok(())
}

