fn days_in_month(year: u16, month: u8) -> Option<u8> {
    let days: u8 = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            let is_leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
            if is_leap { 29 } else { 28 }
        },
        _ => return None,
    };
    Some(days)
}

