struct StringQueue {
    data: Vec<String>,
}

impl StringQueue {
    fn new() -> Self {
        StringQueue { data: Vec::new() }
    }

    fn enqueue(&mut self, item: String) -> Result<(), std::io::Error> {
        self.data.push(item);
        Ok(())
    }

    fn dequeue(&mut self) -> Result<Option<String>, std::io::Error> {
        if self.data.is_empty() {
            return Ok(None);
        }
        let item = self.data.remove(0);
        Ok(Some(item))
    }
}

fn create_string_queue() -> Result<StringQueue, std::io::Error> {
    Ok(StringQueue::new())
}

#[test]
fn test_string_queue() -> Result<(), std::io::Error> {
    let mut q = create_string_queue()?;

    q.enqueue("first".to_string())?;
    q.enqueue("second".to_string())?;

    assert_eq!(q.dequeue()?, Some("first".to_string()));
    assert_eq!(q.dequeue()?, Some("second".to_string()));
    assert_eq!(q.dequeue()?, None);

    q.enqueue("third".to_string())?;
    assert_eq!(q.dequeue()?, Some("third".to_string()));
    assert_eq!(q.dequeue()?, None);

    let mut q2 = create_string_queue()?;
    q2.enqueue("only".to_string())?;
    let _ = q2.dequeue()?; 
    assert_eq!(q2.dequeue()?, None);

    Ok(())
}

