use std::error::Error;
use std::io::{self, Write};

fn sort_vector_in_place(numbers: &mut Vec<i32>) -> Result<(), Box<dyn Error>> {
    let _ = io::stdout().write_all(b"Starting sort...\n")?;
    if numbers.is_empty() {
        let _ = io::stdout().write_all(b"Vector is empty, nothing to sort.\n")?;
        return Ok(());
    }

    let len = numbers.len();
    if len == 1 {
        let _ = io::stdout().write_all(b"Vector has one element, already sorted.\n")?;
        return Ok(());
    }

    for i in 0..len {
        let mut swapped_in_pass = false;
        for j in 0..len - 1 - i {
            let val1 = *numbers.get(j).ok_or(io::Error::new(io::ErrorKind::Other, "Index out of bounds"))?;
            let val2 = *numbers.get(j + 1).ok_or(io::Error::new(io::ErrorKind::Other, "Index out of bounds"))?;

            if val1 > val2 {
                numbers.swap(j, j + 1);
                swapped_in_pass = true;
            }
        }
        if !swapped_in_pass {
            let _ = io::stdout().write_all(b"No swaps in this pass, vector is sorted.\n")?;
            break;
        }
