use std::error::Error;
use std::io::{self, Write};

fn sort_vector_in_place(numbers: &mut Vec<i32>) -> Result<(), Box<dyn Error>> {
    match io::stdout().write_all(b"Starting sort...\n") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    if numbers.is_empty() {
        match io::stdout().write_all(b"Vector is empty, nothing to sort.\n") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        return Ok(());
    }

    let len = numbers.len();
    if len == 1 {
        match io::stdout().write_all(b"Vector has one element, already sorted.\n") {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        return Ok(());
    }

    for i in 0..len {
        let mut swapped_in_pass = false;
        for j in 0..len - 1 - i {
            let val1 = match numbers.get(j).ok_or(io::Error::new(io::ErrorKind::Other, "Index out of bounds")) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };
            let val2 = match numbers.get(j + 1).ok_or(io::Error::new(io::ErrorKind::Other, "Index out of bounds")) {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };

            if *val1 > *val2 {
                numbers.swap(j, j + 1);
                swapped_in_pass = true;
            }
        }
        if !swapped_in_pass {
            match io::stdout().write_all(b"No swaps in this pass, vector is sorted.\n") {
                Ok(v) => v,
                Err(e) => return Err(e.into()),
            };
            break;
        }
    }
    match io::stdout().write_all(b"Sorting complete.\n") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut v1 = vec![3, 1, 4, 1, 5];
    match sort_vector_in_place(&mut v1) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Sorted v1: {:?}", v1);

    let mut v2 = vec![];
    match sort_vector_in_place(&mut v2) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Sorted v2: {:?}", v2);

    let mut v3 = vec![7];
    match sort_vector_in_place(&mut v3) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Sorted v3: {:?}", v3);

    let mut v4 = vec![9, 8, 7, 6, 5, 4, 3, 2, 1];
    match sort_vector_in_place(&mut v4) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("Sorted v4: {:?}", v4);

    match io::stdout().write_all(b"All sorts completed successfully.\n") {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(())
}

