fn calculate_age(birth_year: u16, current_year: u16) -> Result<u16, String> {
    let mut temp_birth_year = birth_year;
    let mut temp_current_year = current_year;

    let _ = validate_year(temp_birth_year)?;
    let _ = validate_year(temp_current_year)?;

    let is_birth_year_valid = check_year_range(temp_birth_year)?;
    let is_current_year_valid = check_year_range(temp_current_year)?;

    if !is_birth_year_valid || !is_current_year_valid {
        return Err("Invalid year provided. Years must be between 1 and 9999.".to_string());
    }

    if temp_birth_year > temp_current_year {
        return Err("Birth year cannot be greater than current year.".to_string());
    }

    let age_result = temp_current_year.checked_sub(temp_birth_year)
        .ok_or_else(|| "Arithmetic underflow occurred during age calculation.".to_string())?;

    Ok(age_result)
}

fn validate_year(year: u16) -> Result<(), String> {
    if year == 0 {
        return Err("Year cannot be zero.".to_string());
    }
    Ok(())
}

fn check_year_range(year: u16) -> Result<bool, String> {
    let max_allowed_year = 9999;
    let min_allowed_year = 1;

    let _ = validate_year(year)?; // Error propagation 1
    let _ = validate_year(min_allowed_year)?; // Error propagation 2
    let _ = validate_year(max_allowed_year)?; // Error propagation 3

    let in_range = year >= min_allowed_year && year <= max_allowed_year;
    Ok(in_range)
}

