fn is_parentheses_balanced(s: &str) -> bool {
    let mut stack = Vec::new();
    for c in s.chars() {
        match c {
            '(' => {
                stack.push(c);
            }
            ')' => {
                if stack.pop().is_none() {
                    return false;
                }
            }
            _ => continue,
        }
    }
    stack.is_empty()
}

