            let current_sum_u8: u8 = sum_i8.try_into()?; // Fourth ?
            if current_sum_u8 == target_sum {
                successful_outcomes += 1;
            }
        }
    }

    let successful_outcomes_f64: f64 = successful_outcomes.try_into()?; // Fifth ?
    let total_outcomes_f64: f64 = total_outcomes.try_into()?; // Sixth ?

