fn add_2x2_matrices(a: [[i32; 2]; 2], b: [[i32; 2]; 2]) -> Result<[[i32; 2]; 2], &'static str> {
    let mut result = [[0; 2]; 2];

    for i in 0..2 {
        for j in 0..2 {
            result[i][j] = a[i][j] + b[i][j];
        }
    }
    Ok(result)
}

fn add_2x2_matrices_safe(a: Option<[[i32; 2]; 2]>, b: Option<[[i32; 2]; 2]>) -> Result<[[i32; 2]; 2], &'static str> {
    let matrix_a = a.ok_or("Matrix A is not 2x2")?;
    let matrix_b = b.ok_or("Matrix B is not 2x2")?;

    let sum = add_2x2_matrices(matrix_a, matrix_b)?; // ? operator 1

    let _ = validate_row_length(sum[0])?; // ? operator 2
    let _ = validate_row_length(sum[1])?; // ? operator 3
    let _ = validate_matrix_dimensions(sum)?; // ? operator 4

    Ok(sum)
}

fn validate_row_length(row: [i32; 2]) -> Result<(), &'static str> {
    if row.len() != 2 {
        Err("Invalid row length")
    } else {
        Ok(())
    }
}

fn validate_matrix_dimensions(matrix: [[i32; 2]; 2]) -> Result<(), &'static str> {
    if matrix.len() != 2 {
        Err("Invalid number of rows")
    } else {
        Ok(())
    }
}

