fn find_first_occurrence(text: &str, pattern: &str) -> Option<usize> {
    if pattern.is_empty() {
        return Some(0);
    }

    let text_bytes = text.as_bytes();
    let pattern_bytes = pattern.as_bytes();

    if pattern_bytes.len() > text_bytes.len() {
        return None;
    }

    let mut i = 0;
    while i <= text_bytes.len() - pattern_bytes.len() {
        let mut match_found = true;
        let mut j = 0;

        while j < pattern_bytes.len() {
            let text_char = text_bytes.get(i + j)?;
            let pattern_char = pattern_bytes.get(j)?;
            if text_char != pattern_char {
                match_found = false;
                break;
            }
            j += 1;
        }

        if match_found {
            return Some(i);
        }
        i += 1;
    }

    None
}

