fn convert_currency(amount: f64, exchange_rate: f64) -> Result<f64, String> {
    if amount < 0.0 {
        return Err("Amount cannot be negative".to_string());
    }
    if exchange_rate < 0.0 {
        return Err("Exchange rate cannot be negative".to_string());
    }

    let product = amount * exchange_rate;
    if product.is_nan() {
        return Err("Calculation resulted in NaN".to_string());
    }
    if product.is_infinite() {
        return Err("Calculation resulted in infinity".to_string());
    }

    Ok(product)
}

