fn is_perfect_number(n: u32) -> bool {
    if n == 0 {
        return false;
    }

    let mut sum_divisors = 1; // 1 is always a divisor
    let limit = (n as f64).sqrt() as u32;

    for i in 2..=limit {
        if n % i == 0 {
            sum_divisors += i;
            if i * i != n {
                sum_divisors += n / i;
            }
        }
    }

    sum_divisors == n
}

