use std::collections::HashMap;
use std::str::SplitWhitespace;

fn parse_cli_args(args_str: &str) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
    let mut args_map = HashMap::new();
    let mut parts: SplitWhitespace = args_str.split_whitespace();

    while let Some(arg_key_prefix) = parts.next() {
        if !arg_key_prefix.starts_with("--") {
            return Err("Expected argument key to start with '--'".into());
        }
        let key = arg_key_prefix.trim_start_matches("--").to_string();

        let value = if let Some(next_part) = parts.next() {
            if next_part.starts_with("--") {
                args_map.insert(key, "".to_string());
                parts = std::iter::once(next_part).chain(parts).collect::<Vec<&str>>().into_iter();
                continue;
            }
            next_part.to_string()
        } else {
            "".to_string()
        };
        args_map.insert(key, value);
    }

    Ok(args_map)
}

