fn char_to_ascii(c: char) -> Result<u8, std::num::TryFromIntError> {
    let s = c.to_string();
    let bytes = s.as_bytes();
    let first_byte = bytes.get(0).ok_or_else(|| {
        std::num::TryFromIntError::try_from(std::convert::Infallible).unwrap_err()
    })?;
    let ascii_value: u8 = (*first_byte).try_into()?;
    Ok(ascii_value)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let char_a = 'A';
    let ascii_a = char_to_ascii(char_a)?;
    println!("ASCII value of '{}': {}", char_a, ascii_a);

    let char_b = 'b';
    let ascii_b = char_to_ascii(char_b)?;
    println!("ASCII value of '{}': {}", char_b, ascii_b);

    let char_newline = '\n';
    let ascii_newline = char_to_ascii(char_newline)?;
    println!("ASCII value of '{}': {}", char_newline, ascii_newline);

    let char_at = '@';
    let ascii_at = char_to_ascii(char_at)?;
    println!("ASCII value of '{}': {}", char_at, ascii_at);

    let char_zero = '0';
    let ascii_zero = char_to_ascii(char_zero)?;
    println!("ASCII value of '{}': {}", char_zero, ascii_zero);

    Ok(())
}

