fn simulate_word_count(file_content: &str) -> Result<usize, std::io::Error> {
    let mut reader = std::io::BufReader::new(file_content.as_bytes());
    let mut line = String::new();
    let mut total_words = 0;

    loop {
        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 {
            break;
        }

        let trimmed_line = line.trim();
        let words: Vec<&str> = if trimmed_line.is_empty() {
            Vec::new()
        } else {
            trimmed_line.split_whitespace().collect()
        };
        total_words += words.len();
        line.clear();
    }

    Ok(total_words)
}

