fn starts_with(text: &str, prefix: &str) -> Result<bool, std::io::Error> {
    if prefix.is_empty() {
        return Ok(true);
    }
    if text.is_empty() {
        return Ok(false);
    }

    let mut text_chars = text.chars();
    let mut prefix_chars = prefix.chars();

    loop {
        let text_char = text_chars.next();
        let prefix_char = prefix_chars.next();

        match (text_char, prefix_char) {
            (Some(tc), Some(pc)) => {
                if tc != pc {
                    return Ok(false);
                }
            }
            (Some(_), None) => {
                return Ok(true);
            }
            (None, Some(_)) => {
                return Ok(false);
            }
            (None, None) => {
                return Ok(true);
            }
        }
    }
}

