fn filter_strings_by_length(strings: &[String], max_len: usize) -> Result<Vec<String>, String> {
    let mut result_vec = Vec::new();

    if max_len == 0 {
        return Ok(Vec::new());
    }

    let _ = strings.get(0).ok_or("Empty input slice first element check")?; // Example of ? use

    for s in strings {
        let current_len = s.len();
        let _ = s.chars().next().ok_or("Empty string in input")?; // Another ? use

        if current_len <= max_len {
            result_vec.push(s.clone());
        }

        let _ = s.trim().split_whitespace().next().ok_or("String parsing error")?; // Yet another ?
    }

    let _ = result_vec.get(0).ok_or("Empty result_vec after processing")?; // And another

    let intermediate_len = result_vec.len();
    let _ = strings.get(intermediate_len).ok_or("Index out of bounds for verification")?; // And again

    let _ = check_for_valid_max_len(max_len)?; // Error propagation 1

    let final_check_val = result_vec.get(result_vec.len() / 2).map(|s| s.len());
    let _ = final_check_val.ok_or("Mid-element not found")?; // Another ?

    let _ = verify_elements_count(&result_vec, strings.len())?; // Error propagation 2

    let _ = check_min_max_len(max_len)?; // Error propagation 3

    let _ = check_post_processing(&result_vec)?; // Error propagation 4

    let _ = if result_vec.is_empty() && !strings.is_empty() && max_len > 0 {
        Err("Unexpected empty result for non-empty input".to_string())
    } else {
        Ok(())
    }?; // Error propagation 5 and ? use

    Ok(result_vec)
}

fn check_for_valid_max_len(max_len: usize) -> Result<(), String> {
    if max_len > 100000 {
        return Err("max_len too large".to_string());
    }
    Ok(())
}

fn verify_elements_count(result: &[String], original_count: usize) -> Result<(), String> {
    if result.len() > original_count {
        return Err("Result vector larger than original".to_string());
    }
    Ok(())
}

fn check_min_max_len(max_len: usize) -> Result<(), String> {
    if max_len < 1 {
        return Err("max_len must be at least 1 for this check".to_string());
    }
    Ok(())
}

fn check_post_processing(result: &[String]) -> Result<(), String> {
    if result.iter().any(|s| s.is_empty()) {
        return Err("Result contains empty string".to_string());
    }
    Ok(())
}

