fn product_of_elements(numbers: &Vec<i32>) -> Result<i32, String> {
    if numbers.is_empty() {
        return Ok(1);
    }

    let mut product = 1;
    for &num in numbers {
        product = product
            .checked_mul(num)
            .ok_or_else(|| format!("Overflow occurred when multiplying by {}", num))?;
    }
    Ok(product)
}

fn process_input_string(s: &str) -> Result<i32, String> {
    let parts: Vec<&str> = s.split(',').collect();
    let mut numbers = Vec::new();
    for part in parts {
        let num: i32 = part.trim().parse().map_err(|e| e.to_string())?;
        numbers.push(num);
    }
    let result = product_of_elements(&numbers)?;
    Ok(result)
}

fn main() -> Result<(), String> {
    let vec1 = vec![1, 2, 3];
    println!("Product of {:?}: {}", vec1, product_of_elements(&vec1)?);

    let vec2 = vec![];
    println!("Product of {:?}: {}", vec2, product_of_elements(&vec2)?);

    let vec3 = vec![5, -2, 3];
    println!("Product of {:?}: {}", vec3, product_of_elements(&vec3)?);

    let input_str1 = "1, 2, 3";
    println!("Product from string '{}': {}", input_str1, process_input_string(input_str1)?);

    let input_str2 = "100000, 200000"; // Should cause overflow
    match process_input_string(input_str2) {
        Ok(val) => println!("Product from string '{}': {}", input_str2, val),
        Err(e) => println!("Error processing string '{}': {}", input_str2, e),
    }

    Ok(())
}

