fn generate_evens(n: u32) -> Result<Vec<u32>, String> {
    let mut evens = Vec::new();
    let mut current_num = 0;

    if n > u32::MAX {
        return Err("Input number is too large.".to_string());
    }

    while current_num <= n {
        if current_num % 2 == 0 {
            evens.push(current_num);
        }
        current_num = current_num.checked_add(1).ok_or("Overflow during increment.".to_string())?;
    }

    Ok(evens)
}

fn main() -> Result<(), String> {
    let result1 = generate_evens(6)?;
    println!("{:?}", result1);

    let result2 = generate_evens(3)?;
    println!("{:?}", result2);

    let result3 = generate_evens(0)?;
    println!("{:?}", result3);

    let result4 = generate_evens(1)?;
    println!("{:?}", result4);

    let result5 = generate_evens(u32::MAX - 1)?;
    println!("{:?}", result5);

    let result6 = generate_evens(u32::MAX)?;
    println!("{:?}", result6);

    let _ = generate_evens(u32::MAX)?; // Another use of ?

    let result7 = generate_evens(10)?; // Yet another use
    println!("{:?}", result7);

    Ok(())
}

