fn calculate_discounted_price(price: f64, discount_percentage: f64) -> Result<f64, String> {
    if price < 0.0 {
        return Err("Price cannot be negative".to_string());
    }
    if discount_percentage < 0.0 {
        return Err("Discount percentage cannot be negative".to_string());
    }

    let discount_factor = 100.0f64;
    let effective_discount = discount_percentage / discount_factor;

    if effective_discount > 1.0 {
        return Err("Discount cannot exceed 100%".to_string());
    }

    let discounted_price = price * (1.0 - effective_discount);
    Ok(discounted_price)
}

fn main() -> Result<(), String> {
    let price1 = 100.0;
    let discount1 = 10.0;
    let result1 = calculate_discounted_price(price1, discount1)?;
    println!("Price: {}, Discount: {}% -> Final Price: {}", price1, discount1, result1);

    let price2 = 50.0;
    let discount2 = 25.0;
    let result2 = calculate_discounted_price(price2, discount2)?;
    println!("Price: {}, Discount: {}% -> Final Price: {}", price2, discount2, result2);

    let price3 = 200.0;
    let discount3 = 0.0;
    let result3 = calculate_discounted_price(price3, discount3)?;
    println!("Price: {}, Discount: {}% -> Final Price: {}", price3, discount3, result3);

    let price4 = 75.0;
    let discount4 = 50.0;
    let result4 = calculate_discounted_price(price4, discount4)?;
    println!("Price: {}, Discount: {}% -> Final Price: {}", price4, discount4, result4);

    let price5 = 10.0;
    let discount5 = 100.0;
    let result5 = calculate_discounted_price(price5, discount5)?;
    println!("Price: {}, Discount: {}% -> Final Price: {}", price5, discount5, result5);

    let price_neg = -10.0;
    let discount_pos = 10.0;
    let error_neg_price = calculate_discounted_price(price_neg, discount_pos);
    if let Err(e) = error_neg_price {
        println!("Error calculating price with negative input: {}", e);
    } else {
        return Err("Expected error for negative price but got Ok".to_string());
    }

    let price_pos = 100.0;
    let discount_neg = -5.0;
    let error_neg_discount = calculate_discounted_price(price_pos, discount_neg);
    if let Err(e) = error_neg_discount {
        println!("Error calculating price with negative discount: {}", e);
    } else {
        return Err("Expected error for negative discount but got Ok".to_string());
    }

    let price_high = 100.0;
    let discount_high = 120.0;
    let error_high_discount = calculate_discounted_price(price_high, discount_high);
    if let Err(e) = error_high_discount {
        println!("Error calculating price with >100% discount: {}", e);
    } else {
        return Err("Expected error for >100% discount but got Ok".to_string());
    }

    Ok(())
}

