fn all_elements_equal(vec: &Vec<i32>) -> Result<bool, Box<dyn std::error::Error>> {
    if vec.is_empty() {
        return Ok(true);
    }

    let first_element = *vec.get(0).ok_or("Vector cannot be empty here")?;
    for &element in vec.iter().skip(1) {
        if element != first_element {
            return Ok(false);
        }
    }
    Ok(true)
}

#[cfg(test)]
