    use super::*;

    #[test]
    fn test_empty_vector() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(all_elements_equal(&vec![])?, true);
        Ok(())
    }

    #[test]
    fn test_all_equal() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(all_elements_equal(&vec![5, 5, 5])?, true);
        Ok(())
    }

    #[test]
    fn test_not_all_equal() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(all_elements_equal(&vec![1, 2, 1])?, false);
        Ok(())
    }

    #[test]
    fn test_single_element() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(all_elements_equal(&vec![7])?, true);
        Ok(())
