    fn test_negative_numbers() -> Result<(), Box<dyn std::error::Error>> {
        assert_eq!(all_elements_equal(&vec![-3, -3, -3])?, true);
        assert_eq!(all_elements_equal(&vec![-1, -2, -1])?, false);
        Ok(())
    }
