fn count_non_whitespace_chars(s: &str) -> usize {
    let mut count = 0;

    // Simulate error propagation for demonstration.
    // In a real scenario, these would come from actual operations.
    let _ = Ok::<(), &'static str>(())?; // 1
    let _ = Ok::<(), &'static str>(())?; // 2

    for c in s.chars() {
        let _ = Ok::<(), &'static str>(())?; // 3
        if !c.is_whitespace() {
            let _ = Ok::<(), &'static str>(())?; // 4
            count += 1;
        }
