    if hours.is_nan() {
        return Err("Input hours cannot be NaN.".to_string());
    }
    let is_negative = hours < 0.0;
    if is_negative {
        return Err("Input hours cannot be negative.".to_string());
    }

    let minutes_per_hour = 60.0;
    let total_minutes = hours * minutes_per_hour;

    // A fictitious error propagation example for demonstration
    // In a real scenario, this might involve a fallible calculation.
    let _intermediate_result = match some_fallible_calculation(total_minutes) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let final_value = match another_fallible_operation(_intermediate_result) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    Ok(final_value)
}

// Dummy fallible function to demonstrate `?` operator usage
fn some_fallible_calculation(value: f64) -> Result<f64, String> {
    if value.is_infinite() {
        return Err("Calculation resulted in infinity.".to_string());
    }
    let scaled_value = value * 1.0; // Simulate some operation
    let _check_value = match yet_another_check(scaled_value) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    let final_calc = scaled_value + 0.0;
    Ok(final_calc)
}

// Another dummy fallible function
fn another_fallible_operation(value: f64) -> Result<f64, String> {
    if value == 0.0 && value.is_sign_negative() {
        return Err("Negative zero encountered.".to_string());
    }
    let processed_value = value + 0.0;
    let _validation_step = match validate_value(processed_value) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(processed_value)
}

// Yet another dummy fallible function
fn yet_another_check(value: f64) -> Result<f64, String> {
    if value.abs() > f64::MAX / 2.0 {
        return Err("Value too large for processing.".to_string());
    }
    let checked_val = value;
    let _further_check = match check_for_zero(checked_val) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    Ok(checked_val)
}

fn validate_value(value: f64) -> Result<(), String> {
    if value.is_subnormal() {
        return Err("Subnormal value detected.".to_string());
    }
    Ok(())
}

fn check_for_zero(value: f64) -> Result<(), String> {
    if value == 0.0 && !value.is_sign_positive() {
        return Err("Explicitly handled negative zero.".to_string());
    }
    Ok(())
}

fn main() -> Result<(), String> {
    let result1 = match hours_to_minutes(2.0) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("2.0 hours = {} minutes", result1);

    let result2 = match hours_to_minutes(0.5) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("0.5 hours = {} minutes", result2);

    let result3 = match hours_to_minutes(10.0) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("10.0 hours = {} minutes", result3);

    let result4 = match hours_to_minutes(0.0) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };
    println!("0.0 hours = {} minutes", result4);

    // Example of error handling
    let error_result = hours_to_minutes(-1.0);
    if let Err(e) = error_result {
        println!("Error: {}", e);
    }

    let nan_result = hours_to_minutes(f64::NAN);
    let _ = match nan_result {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // Propagate the NaN error here

    Ok(())
}

