use std::io::{self, BufRead};

fn harmonic_mean(numbers: &Vec<f64>) -> Result<f64, String> {
    if numbers.is_empty() {
        return Ok(0.0);
    }

    let mut sum_reciprocals = 0.0;
    for &num in numbers {
        if num <= 0.0 {
            return Err("Input numbers must be positive for harmonic mean".to_string());
        }
        sum_reciprocals += 1.0 / num;
    }

    if sum_reciprocals == 0.0 {
        return Err("Sum of reciprocals is zero, division by zero would occur".to_string());
    }

    Ok(numbers.len() as f64 / sum_reciprocals)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let stdin = io::stdin();
    let mut handle = stdin.lock();

    let mut line = String::new();
    handle.read_line(&mut line)?; // ? operator 1
    let num_str = line.trim();

    let nums: Vec<f64> = num_str
        .split_whitespace()
        .map(|s| s.parse::<f64>())
        .collect::<Result<Vec<f64>, _>>()?; // ? operator 2

    let result = harmonic_mean(&nums)?; // ? operator 3
    println!("Harmonic mean: {}", result);

    let test_vec_1 = vec![1.0, 2.0, 4.0];
    let hm1 = harmonic_mean(&test_vec_1)?; // ? operator 4
    println!("HM of [1,2,4]: {}", hm1);

    let test_vec_2 = vec![];
    let hm2 = harmonic_mean(&test_vec_2)?; // ? operator 5
    println!("HM of []: {}", hm2);

    let test_vec_3 = vec![1.0, 1.0, 1.0];
    let hm3 = harmonic_mean(&test_vec_3)?; // ? operator 6
    println!("HM of [1,1,1]: {}", hm3);

    let test_vec_4 = vec![0.5, 2.5, 5.0];
    let hm4 = harmonic_mean(&test_vec_4)?; // ? operator 7
    println!("HM of [0.5, 2.5, 5.0]: {}", hm4);

    let mut another_line = String::new();
    handle.read_line(&mut another_line)?; // ? operator 8
    let another_num_str = another_line.trim();

    let another_nums: Vec<f64> = another_num_str
        .split(',')
        .map(|s| s.parse::<f64>())
        .collect::<Result<Vec<f64>, _>>()?; // ? operator 9

    let another_result = harmonic_mean(&another_nums)?; // ? operator 10
