fn build_http_response(status_code: u16, body: &str) -> Result<String, std::fmt::Error> {
    let mut response = String::new();
    response.push_str("HTTP/1.1 ")?;
    response.push_str(&status_code.to_string())?;
    response.push_str(" ")?;
    match status_code {
        200 => response.push_str("OK")?,
        404 => response.push_str("Not Found")?,
        _ => response.push_str("Unknown")?,
    }
    response.push_str("\r\nContent-Type: text/plain\r\nContent-Length: ")?;
    response.push_str(&body.len().to_string())?;
    response.push_str("\r\n\r\n")?;
    response.push_str(body)?;
    Ok(response)
}

