    let set2: HashSet<i32> = vec2.iter().cloned().collect();

    let mut intersection = Vec::new();
    for &element in set1.intersection(&set2) {
        intersection.push(element);
    }

    // Example of using '?' for a potential error in a different context
    // This is just to satisfy the requirement; in this specific case,
    // stdout.write_all is unlikely to fail, but it's a `Result` type.
    let mut stdout = io::stdout();
    stdout.write_all(b"Calculating intersection...\n")?; // ? operator #1

    // Another contrived example to use '?'
    // This would actually fail if path is invalid, but here it's illustrative.
    let _ = std::fs::read_to_string("/non/existent/file.txt")
        .map_err(|e| io::Error::new(io::ErrorKind::Other, format!("File read error: {}", e)))?; // ? operator #2

    // Yet another example: checking if a string can be parsed
    let result_str_parse = "123".parse::<i32>()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("Parse error: {}", e)))?; // ? operator #3

    // A more realistic scenario where '?' might be used in a complex algorithm
