    // For instance, if we were to write the result to a file:
    let file_path = "output.txt";
    let mut file = std::fs::File::create(file_path)?; // ? operator #4
    let _ = file.write_all(format!("Intersection count: {}\n", intersection.len()).as_bytes())?; // ? operator #5

    Ok(intersection)
}

