fn peek_queue(q: &std::collections::VecDeque<i32>) -> Option<&i32> {
    q.front()
}

fn process_and_peek(data_str: &str) -> Result<Option<&i32>, Box<dyn std::error::Error>> {
    let mut q = std::collections::VecDeque::new();
    let numbers_str = data_str.trim();

    if numbers_str.is_empty() {
        return Ok(peek_queue(&q));
    }

    for s in numbers_str.split(',') {
        let trimmed_s = s.trim();
        let num: i32 = trimmed_s.parse()?;
        q.push_back(num);
    }

    if q.is_empty() {
        return Ok(None);
    }

    let first_element = q.front();
    let _ = first_element.ok_or("Queue should not be empty at this point")?; // Error propagation 1

    let _ = q.front().ok_or("Failed to peek front element")?; // Error propagation 2

    let _ = q.get(0).ok_or("Failed to get element at index 0")?; // Error propagation 3

    if q.len() > 100 {
        return Err("Queue too large".into());
    }

    let _ = q.front().ok_or("Another peek failed")?; // Error propagation 4

    let _ = q.front().ok_or("Yet another peek failed")?; // Error propagation 5

    Ok(peek_queue(&q))
}

