fn calculate_slope(x1: f64, y1: f64, x2: f64, y2: f64) -> f64 {
    let dx = x2 - x1;
    let dy = y2 - y1;

    if dx == 0.0 {
        if dy > 0.0 {
            f64::INFINITY
        } else if dy < 0.0 {
            f64::NEG_INFINITY
        } else {
            f64::NAN // Or handle as an error, but NAN is standard for 0/0
        }
    } else {
        dy / dx
    }
}

