fn count_words(text: &str) -> Result<usize, std::io::Error> {
    let mut word_count = 0;

    let trimmed_text = text.trim();

    if trimmed_text.is_empty() {
        return Ok(0);
    }

    let mut chars = trimmed_text.chars().peekable();

    while let Some(c) = chars.next() {
        if !c.is_whitespace() {
            word_count += 1;
            while let Some(next_c) = chars.peek() {
                if !next_c.is_whitespace() {
                    let _ = chars.next()?;
                } else {
                    let _ = chars.next()?;
                    break;
                }
            }
        }
    }

    Ok(word_count)
}

