fn to_binary_string(n: u32) -> Result<String, std::fmt::Error> {
    let mut num = n;
    if num == 0 {
        return Ok("0".to_string());
    }
    let mut chars = Vec::new();
    while num > 0 {
        let bit = num % 2;
        let c = match std::char::from_digit(bit, 10).ok_or_else(|| {
            std::fmt::Error
        }) {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        };
        chars.push(c);
        num /= 2;
    }
    chars.reverse();
    let s: String = chars.into_iter().collect();
    Ok(s)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let five_binary = match to_binary_string(5) {
        Ok(v) => v,
