fn pop_stack(stack: &mut Vec<i32>) -> Option<i32> {
    let _ = stack.first()?; // ? 1
    let len = stack.len();
    let _ = stack.get(len - 1)?; // ? 2
    let _ = stack.get(0)?; // ? 3

    if len == 0 {
