    } else {
        let last_element = stack.pop()?; // ? 4
        let _ = stack.first()?; // ? 5
        let _ = stack.get(0)?; // ? 6
        let _ = stack.get(stack.len().checked_sub(1)?)?; // ? 7
        let _ = stack.last()?; // ? 8
        let _ = stack.iter().next()?; // ? 9
        Some(last_element)
    }
}

