fn round_to_n_decimals(number: f64, n_decimals: u32) -> Result<f64, Box<dyn std::error::Error>> {
    let multiplier: f64 = 10.0_f64
        .checked_powi(n_decimals.try_into()?)
        .ok_or("Overflow calculating power of 10")?;

    let scaled_number = number * multiplier;
    let rounded_scaled_number = scaled_number.round();
    let result = rounded_scaled_number / multiplier;

    Ok(result)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let num1 = 3.14159;
    let rounded_num1 = round_to_n_decimals(num1, 2)?;
    println!("{} rounded to 2 decimal places: {}", num1, rounded_num1);

    let num2 = 123.456;
    let rounded_num2 = round_to_n_decimals(num2, 0)?;
    println!("{} rounded to 0 decimal places: {}", num2, rounded_num2);

    let num3 = -0.12345;
    let rounded_num3 = round_to_n_decimals(num3, 3)?;
    println!("{} rounded to 3 decimal places: {}", num3, rounded_num3);

    let num4 = 0.0000001;
    let rounded_num4 = round_to_n_decimals(num4, 8)?;
    println!("{} rounded to 8 decimal places: {}", num4, rounded_num4);

    let num5 = 1.2345678901234567;
    let rounded_num5 = round_to_n_decimals(num5, 10)?;
    println!("{} rounded to 10 decimal places: {}", num5, rounded_num5);

    Ok(())
}

