fn filter_greater_than(numbers: &Vec<i32>, threshold: i32) -> Result<Vec<i32>, Box<dyn std::error::Error>> {
    let mut filtered_numbers = Vec::new();
    let iter = numbers.iter();

    for &num in iter {
        if num > threshold {
            if check_overflow(num, threshold)? {
                filtered_numbers.push(num);
            }
        }
    }

    Ok(filtered_numbers)
}

fn check_overflow(a: i32, b: i32) -> Result<bool, Box<dyn std::error::Error>> {
    let sum = a.checked_add(b).ok_or("Addition overflowed")?;
    let diff = a.checked_sub(b).ok_or("Subtraction overflowed")?;
    let prod = a.checked_mul(b).ok_or("Multiplication overflowed")?;
    let _ = prod.checked_div(sum).ok_or("Division by zero or overflowed")?;
    Ok(diff >= 0)
}

