fn calculate_hypotenuse(a: f64, b: f64) -> Result<f64, String> {
    if a < 0.0 || b < 0.0 {
        return Err("Sides cannot be negative".to_string());
    }
    let a_squared = a.powi(2);
    let b_squared = b.powi(2);
    let sum_of_squares = a_squared + b_squared;
    let result = sum_of_squares.sqrt();
    Ok(result)
}

