use std::collections::HashMap;

fn find_single_mode(numbers: &Vec<i32>) -> Result<i32, String> {
    let mut counts: HashMap<i32, usize> = HashMap::new();
    let mut max_count: usize = 0;
    let mut mode: Option<i32> = None;

    if numbers.is_empty() {
        return Err("Cannot find mode of an empty vector".to_string());
    }

    for &num in numbers {
        let count = counts.entry(num).or_insert(0);
        *count += 1;
        if *count > max_count {
            max_count = *count;
            mode = Some(num);
        }
    }

    let result = mode.ok_or_else(|| "Could not determine mode".to_string())?;
    Ok(result)
}

fn main() -> Result<(), String> {
    let test_vec1 = vec![1, 2, 2, 3, 2];
    let mode1 = find_single_mode(&test_vec1)?;
    println!("Mode of {:?} is {}", test_vec1, mode1);

    let test_vec2 = vec![5, 5, 5, 1, 2];
    let mode2 = find_single_mode(&test_vec2)?;
    println!("Mode of {:?} is {}", test_vec2, mode2);

