use std::io::{self, Read};

fn median_of_two_sorted(nums1: &Vec<i32>, nums2: &Vec<i32>) -> io::Result<f64> {
    let mut merged = Vec::new();
    let (mut i, mut j) = (0, 0);

    while i < nums1.len() && j < nums2.len() {
        if nums1[i] < nums2[j] {
            merged.push(nums1[i]);
            i += 1;
        } else {
            merged.push(nums2[j]);
            j += 1;
        }
    }

    while i < nums1.len() {
        merged.push(nums1[i]);
        i += 1;
    }

    while j < nums2.len() {
        merged.push(nums2[j]);
        j += 1;
    }

    let mid_index = merged.len() / 2;
    let median_val = merged.get(mid_index).ok_or_else(|| {
        io::Error::new(io::ErrorKind::Other, "Failed to get median element")
    })?;
    Ok(*median_val as f64)
}

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let mut lines = input.lines();
    let nums1_str = lines.next().ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "Missing first vector")
    })?;
    let nums2_str = lines.next().ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "Missing second vector")
    })?;

    let nums1: Vec<i32> = nums1_str
        .split(',')
        .map(|s| s.trim().parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)))
        .collect::<io::Result<Vec<i32>>>()?;

    let nums2: Vec<i32> = nums2_str
        .split(',')
        .map(|s| s.trim().parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)))
        .collect::<io::Result<Vec<i32>>>()?;

    let median = median_of_two_sorted(&nums1, &nums2)?;
    println!("{}", median);

    Ok(())
}

