fn shift_encode(input: &str, shift_amount: u8) -> Result<String, String> {
    let mut encoded_chars = Vec::new();
    let shift = shift_amount as u32;

    for c in input.chars() {
        let encoded_char = if c.is_ascii_lowercase() {
            let base = 'a' as u32;
            let offset = c as u32 - base;
            let shifted_offset = (offset + shift) % 26;
            std::char::from_u32(base + shifted_offset).ok_or("Invalid character after shift")?
        } else {
            c
        };
        encoded_chars.push(encoded_char);
    }

    String::from_utf8(encoded_chars.into_iter().collect::<String>().into_bytes()).map_err(|e| e.to_string())
}

