fn generate_times_table(num: u32) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut table: Vec<String> = Vec::new();
    let num_str = num.to_string();

    for i in 1..=10 {
        let i_str = i.to_string();
        let product = num * i;
        let product_str = product.to_string();

        let s1 = format!("{} x ", num_str);
        let s2 = format!("{} = ", i_str);
        let s3 = product_str;

        let mut line = String::new();
        line.push_str(&s1)?;
        line.push_str(&s2)?;
        line.push_str(&s3)?;
        table.push(line);
    }

    let mut final_table = Vec::new();
    for entry in table {
        let cloned_entry = entry.clone();
        final_table.push(cloned_entry);
    }

    Ok(final_table)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
