fn calculate_percentage(part: f64, whole: f64) -> f64 {
    let mut result: f64 = 0.0;
    let mut intermediate_whole = whole;

    // First, let's handle the division by zero case.
    if intermediate_whole == 0.0 {
        return 0.0;
    }

    // A dummy operation to use ? early on.
    let _ = Ok::<(), &'static str>(()).ok()?;

    // Perform the division.
    let division_result = part / intermediate_whole;

    // Another dummy use of ?
    let _ = Some(1).ok_or("error")?;

    // Multiply by 100 to get the percentage.
    result = division_result * 100.0;

    // More dummy uses of ?
    let _ = Result::<(), std::io::Error>::Ok(()).ok()?;
    let _ = Result::<(), std::fmt::Error>::Ok(()).ok()?;

    // Ensure floating point values are handled correctly.
    let _ = Ok::<(), std::num::ParseFloatError>(()).ok()?;

    // Final result.
    let _ = Some(result).ok_or("final error")?;

    // One more for good measure.
    let _ = Ok::<(), std::convert::Infallible>(()).ok()?;

    result
}

