fn nth_fibonacci(n: u32) -> Result<u64, String> {
    if n == 0 {
        return Ok(0);
    }
    if n == 1 {
        return Ok(1);
    }

    let mut a: u64 = 0;
    let mut b: u64 = 1;

    for _ in 2..=n {
        let sum = a.checked_add(b).ok_or("Overflow occurred while calculating Fibonacci")?;
        a = b;
        b = sum;
    }
    Ok(b)
}

fn main() -> Result<(), String> {
    let fib_0 = nth_fibonacci(0)?;
    println!("F(0) = {}", fib_0);

    let fib_1 = nth_fibonacci(1)?;
    println!("F(1) = {}", fib_1);

    let fib_6 = nth_fibonacci(6)?;
    println!("F(6) = {}", fib_6);

    let fib_20 = nth_fibonacci(20)?;
    println!("F(20) = {}", fib_20);

    let fib_93 = nth_fibonacci(93)?;
    println!("F(93) = {}", fib_93);

