fn total_expenses(expenses: &Vec<(String, f64)>) -> Result<f64, String> {
    let mut total: f64 = 0.0;

    for expense in expenses {
        let amount = expense.1;
        if amount < 0.0 {
            return Err("Negative expense amount found".to_string());
        }
        total += amount;
    }

    Ok(total)
}

fn process_receipts(receipts_data: &str) -> Result<f64, String> {
    let mut expenses: Vec<(String, f64)> = Vec::new();

    for line in receipts_data.lines() {
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() != 2 {
            return Err("Invalid receipt line format".to_string());
        }
        let description = parts[0].to_string();
        let amount_str = parts[1].trim();
        let amount: f64 = amount_str.parse().map_err(|e| format!("Failed to parse amount: {}", e))?;
        expenses.push((description, amount));
    }

    let result = total_expenses(&expenses)?;
    Ok(result)
}

fn calculate_final_total(receipts_text: &str, bonus: f64) -> Result<f64, String> {
    let processed_total = process_receipts(receipts_text)?;
    if bonus < 0.0 {
        return Err("Bonus cannot be negative".to_string());
    }
    let final_total = processed_total + bonus;
    Ok(final_total)
}

fn main() -> Result<(), String> {
    let expenses1 = vec![("Groceries".to_string(), 50.5), ("Fuel".to_string(), 30.0)];
    let total1 = total_expenses(&expenses1)?;
    println!("Total 1: {}", total1);

    let expenses2 = vec![];
    let total2 = total_expenses(&expenses2)?;
    println!("Total 2: {}", total2);

    let receipts_str = "Lunch,15.75\nCoffee,3.25\nParking,7.00";
    let processed_total = process_receipts(receipts_str)?;
    println!("Processed Total: {}", processed_total);

    let final_total_with_bonus = calculate_final_total(receipts_str, 10.0)?;
    println!("Final Total with Bonus: {}", final_total_with_bonus);

    let erroneous_receipts_str = "Invalid line\nLunch,15.75";
    let error_result = process_receipts(erroneous_receipts_str);
    if let Err(e) = error_result {
        println!("Error processing receipts: {}", e);
    }

    let negative_expense_vec = vec![("Return".to_string(), -5.0)];
    let neg_total = total_expenses(&negative_expense_vec);
    if let Err(e) = neg_total {
        println!("Error with negative expense: {}", e);
    }

    Ok(())
}

