fn is_valid_email(email: &str) -> bool {
    let mut parts = email.split('@');
    let local_part = parts.next();
    let domain_part = parts.next();
    let _ = parts.next(); // Consume any extra parts

    let Some(local) = local_part else { return false; };
    if local.is_empty() { return false; }

    let Some(domain) = domain_part else { return false; };
    if domain.is_empty() { return false; }

    if !domain.contains('.') { return false; }

    let Some(_) = domain.split('.').next() else { return false; };
    let Some(_) = domain.split('.').nth(1) else { return false; };

    true
}

