    let dy_str = (y2 - y1).to_string();

    let dx_squared_str = (dx_str.parse::<f64>()? * dx_str.parse::<f64>()?).to_string();
    let dy_squared_str = (dy_str.parse::<f64>()? * dy_str.parse::<f64>()?).to_string();

    let sum_of_squares_str = (dx_squared_str.parse::<f64>()? + dy_squared_str.parse::<f64>()?).to_string();

    // Simulate another error propagation for demonstration
