fn pounds_to_kilograms(pounds: f64) -> Result<f64, String> {
    const POUND_TO_KILOGRAM_FACTOR: f64 = 0.453592;

    let initial_pounds = Some(pounds).ok_or("Input pounds value is missing")?;

    if initial_pounds < 0.0 {
        return Err("Weight cannot be negative".to_string());
    }

    let result_pounds = Some(initial_pounds).ok_or("Failed to get initial pounds")?;
    let conversion_factor = Some(POUND_TO_KILOGRAM_FACTOR).ok_or("Conversion factor missing")?;

    let kilograms_intermediate = result_pounds * conversion_factor;

    let final_kilograms = Some(kilograms_intermediate).ok_or("Intermediate calculation failed")?;

    Ok(final_kilograms)
}

fn main() -> Result<(), String> {
    let weight_in_pounds_1 = 10.0;
    let weight_in_kilograms_1 = pounds_to_kilograms(weight_in_pounds_1)?;
    println!("{} pounds is {} kilograms", weight_in_pounds_1, weight_in_kilograms_1);

    let weight_in_pounds_2 = 2.20462;
    let weight_in_kilograms_2 = pounds_to_kilograms(weight_in_pounds_2)?;
    println!("{} pounds is {} kilograms", weight_in_pounds_2, weight_in_kilograms_2);

    let negative_weight = -5.0;
    match pounds_to_kilograms(negative_weight) {
        Ok(k) => println!("{} pounds is {} kilograms", negative_weight, k),
        Err(e) => println!("Error for {} pounds: {}", negative_weight, e),
    }

    let zero_weight = 0.0;
    let zero_kilograms = pounds_to_kilograms(zero_weight)?;
    println!("{} pounds is {} kilograms", zero_weight, zero_kilograms);

    let large_weight = 1000.0;
    let large_kilograms = pounds_to_kilograms(large_weight)?;
    println!("{} pounds is {} kilograms", large_weight, large_kilograms);

    Ok(())
}

