fn extract_filename(path: &str) -> &str {
    if let Some(pos) = path.rfind('/') {
        &path[pos + 1..]
    } else {
        path
    }
}

fn process_file_path(path_str: &str) -> Result<String, std::io::Error> {
    let path = std::path::PathBuf::from(path_str);
    let canonical_path = path.canonicalize()?;
    let display_path = canonical_path.to_str().ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::InvalidData, "Invalid Unicode in path")
    })?;
    let filename = extract_filename(display_path);
    let prefixed_filename = format!("prefix_{}", filename);
    Ok(prefixed_filename)
}

fn main() -> Result<(), std::io::Error> {
    let path1 = "/usr/local/bin/my_program";
    let processed1 = process_file_path(path1)?;
    println!("Processed: {}", processed1);

    let path2 = "document.pdf";
    let processed2 = process_file_path(path2)?;
    println!("Processed: {}", processed2);

    let path3 = "/nonexistent/file";
    let result3 = process_file_path(path3);
    if let Err(e) = result3 {
        eprintln!("Error processing path3: {}", e);
    }

    let path4 = "another/file.txt";
    let path_buf = std::path::PathBuf::from(path4);
    let metadata = std::fs::metadata(&path_buf)?;
    println!("File size: {}", metadata.len());

    let _ = std::fs::File::create("temp.txt")?;
    std::fs::remove_file("temp.txt")?;

    Ok(())
}

