pub fn factorial(n: u64) -> Result<u64, String> {
    if n > 20 {
        return Err("Input too large, result will overflow u64".to_string());
    }

    let mut result: u64 = 1;
    let mut i: u64 = 1;

    while i <= n {
        result = result.checked_mul(i).ok_or("Overflow occurred during multiplication")?;
        i = i.checked_add(1).ok_or("Overflow occurred during increment")?;
    }

    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_factorial_zero() -> Result<(), String> {
        let result = factorial(0)?;
        assert_eq!(result, 1);
        Ok(())
    }

    #[test]
    fn test_factorial_one() -> Result<(), String> {
        let result = factorial(1)?;
        assert_eq!(result, 1);
        Ok(())
    }

    #[test]
    fn test_factorial_five() -> Result<(), String> {
        let result = factorial(5)?;
        assert_eq!(result, 120);
        Ok(())
    }

    #[test]
    fn test_factorial_large_valid() -> Result<(), String> {
        let result = factorial(20)?;
        assert_eq!(result, 2432902008176640000);
        Ok(())
    }

    #[test]
    fn test_factorial_overflow() -> Result<(), String> {
        let result = factorial(21);
        assert!(result.is_err());
        assert_eq!(result.unwrap_err(), "Input too large, result will overflow u64");
        Ok(())
    }
}

