fn roman_to_int(s: &str) -> Result<u32, &'static str> {
    let mut total = 0;
    for c in s.chars() {
        let value = match c {
            'I' => 1,
            'V' => 5,
            'X' => 10,
            _ => return Err("Invalid Roman numeral character"),
        };
        total += value;
    }
    Ok(total)
}

