        assert_eq!(roman_to_int("X")?, 10);
        assert_eq!(roman_to_int("VI")?, 6);
        assert_eq!(roman_to_int("VII")?, 7);
        assert_eq!(roman_to_int("XII")?, 12);
        assert_eq!(roman_to_int("XX")?, 20);
