fn play_rps_round(p1_choice: char, p2_choice: char) -> Result<String, String> {
    let p1_valid = validate_choice(p1_choice)?;
    let p2_valid = validate_choice(p2_choice)?;

    if p1_valid == p2_valid {
        return Ok("Tie".to_string());
    }

    let result = match (p1_valid, p2_valid) {
        ('R', 'S') | ('S', 'P') | ('P', 'R') => "Player 1",
        ('S', 'R') | ('P', 'S') | ('R', 'P') => "Player 2",
        _ => return Err("Unexpected game state".to_string()),
    };

    Ok(result.to_string())
}

fn validate_choice(choice: char) -> Result<char, String> {
    let valid_choice = match choice {
        'R' => 'R',
        'P' => 'P',
        'S' => 'S',
        _ => return Err(format!("Invalid choice: {}", choice)),
    };
    Ok(valid_choice)
}

fn main() -> Result<(), String> {
    println!("{}", play_rps_round('R', 'S')?);
    println!("{}", play_rps_round('P', 'P')?);
    println!("{}", play_rps_round('S', 'R')?);
    println!("{}", play_rps_round('R', 'P')?);
    println!("{}", play_rps_round('X', 'S').unwrap_or_else(|e| format!("Error: {}", e)));

