    println!("{}", result1);

    let result2 = play_rps_round('S', 'P')?;
    println!("{}", result2);

    let result3 = play_rps_round('R', 'R')?;
    println!("{}", result3);

    let result4 = play_rps_round('S', 'S')?;
    println!("{}", result4);

    Ok(())
}

