    use super::*;

    #[test]
    fn test_is_anagram_true() -> Result<(), Box<dyn std::error::Error>> {
        assert!(is_anagram("listen", "silent")?);
        assert!(is_anagram("Debit Card", "Bad Credit")?);
        assert!(is_anagram("Anagram", "Nag a ram")?);
        assert!(is_anagram("A gentleman", "Elegant man")?);
        Ok(())
    }

    #[test]
    fn test_is_anagram_false() -> Result<(), Box<dyn std::error::Error>> {
        assert!(!is_anagram("hello", "world")?);
        assert!(!is_anagram("rust", "trust")?);
