fn remove_duplicates_sorted(nums: &Vec<i32>) -> Result<Vec<i32>, String> {
    if nums.is_empty() {
        return Ok(Vec::new());
    }

    let mut result = Vec::with_capacity(nums.len());
    let first_element = nums.get(0).ok_or("Vector unexpectedly empty after check")?;
    result.push(*first_element);

    let mut prev = *first_element;

    for i in 1..nums.len() {
        let current = nums.get(i).ok_or("Error accessing vector element")?;
        if *current != prev {
            result.push(*current);
            prev = *current;
        }
    }

    Ok(result)
}

