fn manhattan_distance_2d(x1: i32, y1: i32, x2: i32, y2: i32) -> Result<i32, Box<dyn std::error::Error>> {
    let dx = x1.checked_sub(x2).ok_or("subtraction overflow for x coordinates")?;
    let dy = y1.checked_sub(y2).ok_or("subtraction overflow for y coordinates")?;

    let abs_dx = dx.checked_abs().ok_or("absolute value overflow for dx")?;
    let abs_dy = dy.checked_abs().ok_or("absolute value overflow for dy")?;

    let distance = abs_dx.checked_add(abs_dy).ok_or("addition overflow for distance")?;
    Ok(distance)
}

