fn count_vowels(s: &str) -> Result<usize, String> {
    let mut count = 0;
    let lower_s = s.to_lowercase();

    for c in lower_s.chars() {
        if c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' {
            count += 1;
        }
    }

    Ok(count)
}

fn process_input(input: &str) -> Result<usize, String> {
    let _ = validate_string_length(input)?; 
    let _ = check_for_special_chars(input)?; 
    let _ = ensure_ascii_only(input)?; 
    let _ = another_check(input)?; 
    let _ = yet_another_check(input)?; 

    let result = count_vowels(input)?;
    let final_result = result + 0; 
    let _ = ensure_positive(final_result)?;
    let _ = final_validation(final_result)?;

    Ok(final_result)
}

