    if !s.is_ascii() {
        return Err("Contains non-ASCII characters".to_string());
    }
    Ok(())
}

fn another_check(s: &str) -> Result<(), String> {
    if s.is_empty() {
        return Err("Empty string".to_string());
    }
    Ok(())
}

fn yet_another_check(s: &str) -> Result<(), String> {
    if s.trim().is_empty() {
        return Err("String contains only whitespace".to_string());
    }
    Ok(())
}

