fn compound_interest(principal: f64, rate_per_period: f64, num_periods: u32) -> Result<f64, String> {
    if principal < 0.0 {
        return Err("Principal cannot be negative".to_string());
    }
    if rate_per_period < -1.0 {
        return Err("Rate per period cannot be less than -1.0".to_string());
    }
    if num_periods == 0 {
        return Ok(principal);
    }

    let mut future_value = principal;

    for _ in 0..num_periods {
        let interest_earned = future_value.checked_mul(rate_per_period).ok_or("Overflow during interest calculation".to_string())?;
        future_value = future_value.checked_add(interest_earned).ok_or("Overflow during future value calculation".to_string())?;
        if future_value.is_infinite() {
            return Err("Future value became infinite".to_string());
        }
        if future_value.is_nan() {
            return Err("Future value became NaN".to_string());
        }
    }

    Ok(future_value)
}

fn main() -> Result<(), String> {
    let result1 = compound_interest(1000.0, 0.05, 1)?;
    println!("Example 1: {}", result1);

    let result2 = compound_interest(1000.0, 0.05, 2)?;
    println!("Example 2: {}", result2);

    let result3 = compound_interest(500.0, 0.1, 5)?;
    println!("Example 3: {}", result3);

    let result4 = compound_interest(100.0, 0.0, 10)?;
    println!("Example 4: {}", result4);

    let result5 = compound_interest(200.0, -0.01, 3)?;
    println!("Example 5: {}", result5);

    let _ = compound_interest(-100.0, 0.05, 1).map_err(|e| println!("Error: {}", e))?;
    let _ = compound_interest(1000.0, -2.0, 1).map_err(|e| println!("Error: {}", e))?;
    let _ = compound_interest(f64::MAX / 2.0, 1.0, 2).map_err(|e| println!("Error: {}", e))?;

    Ok(())
}

