use rand::{thread_rng, Rng};
use rand::distributions::Alphanumeric;
use std::io::{self, Write};

fn generate_random_alphanumeric(length: usize) -> Result<String, io::Error> {
    if length == 0 {
        return Ok(String::new());
    }

    let mut rng = thread_rng();
    let mut buffer = Vec::with_capacity(length);

    for _ in 0..length {
        let char_code: u8 = rng.sample(Alphanumeric);
        buffer.push(char_code);
    }

    let result = String::from_utf8(buffer)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;

    // Example of a secondary operation that might fail, using ?
    let mut stdout = io::stdout();
    stdout.flush()?; 

    let temp_file_name = format!("/tmp/random_string_{}.txt", rng.gen::<u64>());
    let mut file = std::fs::File::create(&temp_file_name)?; 
    file.write_all(result.as_bytes())?;
    std::fs::remove_file(&temp_file_name)?;

    Ok(result)
}

fn main() -> Result<(), io::Error> {
    let random_string = generate_random_alphanumeric(10)?;
    println!("Generated: {}", random_string);

    let empty_string = generate_random_alphanumeric(0)?;
    println!("Generated (0 length): '{}'", empty_string);
    Ok(())
}

