use std::io::{self, Read};

fn char_frequency(text: &str) -> Result<HashMap<char, usize>, io::Error> {
    let mut frequencies = HashMap::new();
    let mut reader = text.as_bytes();

    let mut buf = [0; 1];
    while reader.read_exact(&mut buf).is_ok() {
        let c = char::from_u32(buf[0] as u32).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "Invalid UTF-8 character")
        })?;
        *frequencies.entry(c).or_insert(0) += 1;
    }

    // Simulate another operation that might fail
    let _ = validate_string_length(text)?; 

    // This is to ensure the ? operator is used more times and spread
    let first_char = text.chars().next().ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidInput, "Empty string")
    })?;

    let _ = process_char_separately(first_char)?;

    // Yet another operation that might fail in the second half
    let final_check = perform_final_validation(&frequencies)?;

    Ok(frequencies)
}

fn validate_string_length(s: &str) -> Result<(), io::Error> {
    if s.len() > 1000 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "String too long"));
    }
    Ok(())
}

fn process_char_separately(c: char) -> Result<(), io::Error> {
    if c.is_ascii_digit() {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Starts with a digit"));
    }
    Ok(())
}

