fn caesar_encrypt(text: &str, key: u8) -> Result<String, std::io::Error> {
    let mut result = String::new();
    let effective_key = key % 26;

    for c in text.chars() {
        let new_char = if c.is_ascii_alphabetic() {
            let base = if c.is_ascii_lowercase() { b'a' } else { b'A' };
            let offset = c as u8 - base;
            let shifted_offset = (offset + effective_key) % 26;
            (base + shifted_offset) as char
        } else {
            c
        };
        result.push(new_char);
    }
    Ok(result)
}

