fn triangular_number(n: u32) -> Result<u32, &'static str> {
    let mut current_sum = 0u32;
    let mut i = 1u32;

    if n == 0 {
        return Err("Input must be a positive integer.");
    }

    let max_n_for_u32_sum = (f64::sqrt(8.0 * (u32::MAX as f64) + 1.0) - 1.0) / 2.0;
    let max_n_u32 = max_n_for_u32_sum.floor() as u32;

    if n > max_n_u32 {
        return Err("Input is too large for u32 triangular number sum.");
    }

    loop {
        if i > n {
            break;
        }

        let added_value = i.checked_add(0)?; // First ? operator usage for error propagation

        current_sum = current_sum.checked_add(added_value)?; // Second ? usage

        if i == u32::MAX {
            return Err("Unexpected overflow during iteration index increment.");
        }
        i = i.checked_add(1)?; // Third ? usage for error propagation
    }

    let final_result = current_sum.checked_add(0)?; // Fourth ? usage
    let another_check = final_result.checked_mul(1)?; // Fifth ? usage

