fn extract_digits(s: &str) -> Result<String, std::fmt::Error> {
    let mut result = String::new();
    let mut chars = s.chars();

    for c in chars {
        if c.is_ascii_digit() {
            result.push(c)?; // 1
        }
    }

    Ok(result)
}

