pub fn trim_string(input: &str) -> Result<String, std::io::Error> {
    let s = input.to_string();

    let mut chars = s.chars();
    let first_non_whitespace_idx = chars
        .by_ref()
        .position(|c| !c.is_whitespace())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidInput, "Empty string or all whitespace"))?;

    let non_empty_chars: String = input.chars().skip(first_non_whitespace_idx).collect();
    let mut reversed_chars = non_empty_chars.chars().rev();

    let last_non_whitespace_offset_from_end = reversed_chars
        .by_ref()
        .position(|c| !c.is_whitespace())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidInput, "Should not happen for non-empty string"))?;

    let len = non_empty_chars.len();
    let end_idx = len - last_non_whitespace_offset_from_end;

    let trimmed_str_slice = non_empty_chars
        .get(..end_idx)
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidInput, "Slice error"))?;

    Ok(trimmed_str_slice.to_string())
}

