use std::collections::HashMap;

fn find_modes(numbers: &Vec<i32>) -> Result<Vec<i32>, &'static str> {
    let mut counts: HashMap<i32, usize> = HashMap::new();

    for &num in numbers {
        *counts.entry(num).or_insert(0) += 1;
    }

    if counts.is_empty() {
        return Ok(Vec::new());
    }

    let max_count = counts.values().cloned().max().ok_or("Failed to find max count")?;

    let mut modes = Vec::new();
    for (num, count) in counts {
        if count == max_count {
            modes.push(num);
        }
    }

    Ok(modes)
}

#[test]
fn test_basic_modes() -> Result<(), &'static str> {
    let result = find_modes(&vec![1, 2, 2, 3, 3, 4])?;
    assert!(result.contains(&2));
    assert!(result.contains(&3));
    assert_eq!(result.len(), 2);
    Ok(())
}

#[test]
fn test_single_mode() -> Result<(), &'static str> {
    let result = find_modes(&vec![5, 5, 5])?;
    assert_eq!(result, vec![5]);
    Ok(())
}

#[test]
fn test_empty_vector() -> Result<(), &'static str> {
    let result = find_modes(&vec![])?;
    assert!(result.is_empty());
    Ok(())
}

#[test]
fn test_all_unique() -> Result<(), &'static str> {
    let result = find_modes(&vec![1, 2, 3, 4])?;
    assert!(result.contains(&1));
    assert!(result.contains(&2));
    assert!(result.contains(&3));
    assert!(result.contains(&4));
    assert_eq!(result.len(), 4);
    Ok(())
}

