impl std::str::FromStr for BmiInput {
    type Err = BmiError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() != 2 {
            return Err(BmiError::InvalidInputFormat);
        }
        let weight_str = parts[0].trim();
        let height_str = parts[1].trim();

        let weight_kg: f64 = weight_str.parse()?;
        let height_m: f64 = height_str.parse()?;

        Ok(BmiInput { weight_kg, height_m })
    }
}

enum BmiError {
    InvalidInputFormat,
    NegativeValue,
    ZeroHeight,
    ParseError(std::num::ParseFloatError),
}

impl From<std::num::ParseFloatError> for BmiError {
    fn from(err: std::num::ParseFloatError) -> Self {
        BmiError::ParseError(err)
    }
}

struct BmiInput {
    weight_kg: f64,
    height_m: f64,
}

fn calculate_bmi(weight_kg: f64, height_m: f64) -> Result<f64, BmiError> {
    if weight_kg <= 0.0 {
        return Err(BmiError::NegativeValue);
    }
    if height_m <= 0.0 {
        return Err(BmiError::ZeroHeight);
    }
    let bmi = weight_kg / (height_m * height_m);
    Ok(bmi)
}

fn process_bmi_string(input_str: &str) -> Result<f64, BmiError> {
    let bmi_input: BmiInput = input_str.parse()?;
    let weight = bmi_input.weight_kg;
    let height = bmi_input.height_m;

    let bmi = calculate_bmi(weight, height)?;
    Ok(bmi)
}

fn main() -> Result<(), BmiError> {
    let input1 = "70.0, 1.75";
    let bmi1 = process_bmi_string(input1)?;
    println!("BMI for '{}': {:.2}", input1, bmi1);

    let input2 = "90.0, 1.80";
    let bmi2 = process_bmi_string(input2)?;
    println!("BMI for '{}': {:.2}", input2, bmi2);

    let input3 = "65, 1.60";
    let bmi3 = process_bmi_string(input3)?;
    println!("BMI for '{}': {:.2}", input3, bmi3);

    let input4 = "invalid input";
    let _ = process_bmi_string(input4)?;

    let input5 = "70.0, 0.0";
    let _ = process_bmi_string(input5)?;

    Ok(())
}

