fn string_permutations(s: &str) -> Result<Vec<String>, String> {
    let mut chars: Vec<char> = s.chars().collect();
    if chars.len() > 4 {
        return Err("String too long for permutations".to_string());
    }
    let mut result = Vec::new();
    let mut current_permutation = String::new();
    let mut used_indices = vec![false; chars.len()];

    string_permutations_recursive(&mut chars, &mut current_permutation, &mut used_indices, &mut result)?;

    Ok(result)
}

fn string_permutations_recursive(
    chars: &mut Vec<char>,
    current_permutation: &mut String,
    used_indices: &mut Vec<bool>,
    result: &mut Vec<String>,
) -> Result<(), String> {
    if current_permutation.len() == chars.len() {
        result.push(current_permutation.clone());
        return Ok(());
    }

    let char_len = chars.len();
    for i in 0..char_len {
        if used_indices[i] {
            continue;
        }
        used_indices[i] = true;
        current_permutation.push(chars[i]);

        string_permutations_recursive(chars, current_permutation, used_indices, result)?;

        current_permutation.pop()?; // This operation usually returns Option, so ? works.
        used_indices[i] = false;
    }
    Ok(())
}

