use std::io::{self, BufReader};
use std::fs::File;
use std::io::prelude::*;

fn flatten_options(input: Vec<Option<i32>>) -> Vec<i32> {
    input.into_iter().filter_map(|x| x).collect()
}

fn read_and_process_numbers(path: &str) -> io::Result<Vec<i32>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut results = Vec::new();

    for line_result in reader.lines() {
        let line = line_result?;
        let parsed_option: Option<i32> = line.parse().ok();
        results.push(parsed_option);
    }
    Ok(flatten_options(results))
}

fn main() -> io::Result<()> {
    let data = vec![Some(1), None, Some(2), Some(3), None];
    let flattened = flatten_options(data);
    println!("{:?}", flattened);

    let empty_data: Vec<Option<i32>> = vec![None, None];
    let empty_flattened = flatten_options(empty_data);
    println!("{:?}", empty_flattened);

    // Create a dummy file for testing read_and_process_numbers
    let mut file = File::create("numbers.txt")?;
    writeln!(file, "1")?;
    writeln!(file, "hello")?; // This line will be ignored by parse().ok()
    writeln!(file, "2")?;
    writeln!(file, "3")?;
    writeln!(file, "world")?; // This line will also be ignored

    let processed_numbers = read_and_process_numbers("numbers.txt")?;
    println!("Processed from file: {:?}", processed_numbers);

    // Test a non-existent file
    let non_existent_result = read_and_process_numbers("non_existent.txt");
    match non_existent_result {
        Ok(_) => println!("Unexpected success with non-existent file."),
        Err(e) => println!("Expected error for non-existent file: {}", e),
    }

    Ok(())
}

