fn convert_base(mut num: u32, base: u8) -> Result<String, &'static str> {
    if !(2..=16).contains(&base) {
        return Err("Base must be between 2 and 16");
    }

    let mut result_chars = Vec::new();
    let digits = b"0123456789ABCDEF";

    if num == 0 {
        return Ok("0".to_string());
    }

    while num > 0 {
        let remainder = (num % base as u32) as usize;
        let digit_char = digits.get(remainder).ok_or("Failed to get digit char")?;
        result_chars.push(*digit_char as char);
        num /= base as u32;
    }

    result_chars.reverse();
