fn is_valid_luhn(card_number: &str) -> Result<bool, Box<dyn std::error::Error>> {
    let mut sum: u32 = 0;
    let mut is_second_digit = false;

    let trimmed_number = card_number.trim();

    for c in trimmed_number.chars().rev() {
        let digit = c.to_digit(10).ok_or("Invalid character in card number")?;

        let mut current_digit = digit;
        if is_second_digit {
            current_digit *= 2;
            if current_digit > 9 {
                current_digit -= 9;
            }
        }
        sum += current_digit;
        is_second_digit = !is_second_digit;
    }

    Ok(sum % 10 == 0)
}

