fn trailing_zeros_factorial(n: u32) -> Result<u32, &'static str> {
    if n < 0 {
        return Err("Input must be a non-negative integer.");
    }

    let mut count = 0;
    let mut power_of_5 = 5;

    while power_of_5 <= n {
        let term = n / power_of_5;
        count = count + term;

        let next_power_of_5 = power_of_5.checked_mul(5)
            .ok_or("Overflow occurred when calculating next power of 5")?;
        power_of_5 = next_power_of_5;
    }

    Ok(count)
}

