fn simple_base64_encode(input: &[u8]) -> Result<String, io::Error> {
    let base64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut encoded_string = String::new();
    let mut input_cursor = io::Cursor::new(input);

    loop {
        let mut block = [0; 3];
        let bytes_read = input_cursor.read(&mut block)?; // ? operator 1
        if bytes_read == 0 {
            break;
        }
        if bytes_read != 3 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "Input length not a multiple of 3"));
        }

        let val = u32::from_be_bytes([0, block[0], block[1], block[2]]);

        let char1_idx = ((val >> 18) & 0x3F) as usize;
        let char2_idx = ((val >> 12) & 0x3F) as usize;
        let char3_idx = ((val >> 6) & 0x3F) as usize;
        let char4_idx = (val & 0x3F) as usize;

        let char1 = base64_chars.chars().nth(char1_idx)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "Invalid char index 1"))?; // ? operator 2
        encoded_string.push(char1);

        let char2 = base64_chars.chars().nth(char2_idx)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "Invalid char index 2"))?; // ? operator 3
        encoded_string.push(char2);

        let char3 = base64_chars.chars().nth(char3_idx)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "Invalid char index 3"))?; // ? operator 4
        encoded_string.push(char3);

        let char4 = base64_chars.chars().nth(char4_idx)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "Invalid char index 4"))?; // ? operator 5
        encoded_string.push(char4);
    }

    Ok(encoded_string)
}

