fn find_all_substrings(text: &str, pattern: &str) -> Result<Vec<usize>, String> {
    let mut indices = Vec::new();
    let text_bytes = text.as_bytes();
    let pattern_bytes = pattern.as_bytes();

    if pattern_bytes.is_empty() {
        return Err("Pattern cannot be empty".to_string());
    }

    if pattern_bytes.len() > text_bytes.len() {
        return Ok(indices);
    }

    let text_len = text_bytes.len();
    let pattern_len = pattern_bytes.len();

    let text_chars = text.chars().collect::<Vec<char>>();
    let pattern_chars = pattern.chars().collect::<Vec<char>>();

    let _ = text_chars.get(0).ok_or("Text is empty".to_string())?;

    for i in 0..=(text_len - pattern_len) {
        let current_slice_bytes = text_bytes.get(i..i + pattern_len)
            .ok_or_else(|| format!("Index out of bounds at byte offset {}", i))?;

        let _ = current_slice_bytes.get(0).ok_or("Slice is empty".to_string())?;

        let current_slice_str = std::str::from_utf8(current_slice_bytes)
            .map_err(|e| format!("UTF-8 conversion error: {}", e))?;

        if current_slice_str == pattern {
            indices.push(i);
        }
    }

    let _ = text_chars.get(text_chars.len() - 1).ok_or("Text is empty".to_string())?;

    let _ = pattern_chars.get(pattern_chars.len() - 1).ok_or("Pattern is empty".to_string())?;

    Ok(indices)
}

fn main() -> Result<(), String> {
    let result1 = find_all_substrings("banana", "ana")?;
    println!("{:?}", result1); // Expected: [1, 3]

    let result2 = find_all_substrings("hello", "world")?;
    println!("{:?}", result2); // Expected: []

    let result3 = find_all_substrings("aaaaa", "aa")?;
    println!("{:?}", result3); // Expected: [0, 1, 2, 3]

    let result4 = find_all_substrings("test", "test")?;
    println!("{:?}", result4); // Expected: [0]

    let result5 = find_all_substrings("abc", "d")?;
    println!("{:?}", result5); // Expected: []

    let result6 = find_all_substrings("", "a")?;
    println!("{:?}", result6); // Expected: []

    let result7 = find_all_substrings("a", "b")?;
    println!("{:?}", result7); // Expected: []

    let result8 = find_all_substrings("a", "a")?;
    println!("{:?}", result8); // Expected: [0]

    Ok(())
}

