use std::io::{self, Write};

fn pascals_triangle_row(row_index: u32) -> Result<Vec<u64>, io::Error> {
    if row_index == 0 {
        return Ok(vec![1]);
    }

    let mut row = vec![1];
    let mut prev_val: u64 = 1;

    for i in 1..=row_index {
        let current_val = prev_val
            .checked_mul(row_index - i + 1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "Overflow during multiplication"))?
            .checked_div(i)
            .ok_or_else(|| io::Error::new(io::ErrorKind::Other, "Division by zero (should not happen)"))?;
        row.push(current_val);
        prev_val = current_val;
    }

    // Example of using ? for a non-error case, just to fulfill the requirement
    // In a real scenario, this wouldn't typically be an error.
    let _ = io::stdout().write_all(b"Generated row\n")?;

    if row.is_empty() {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "Generated row is empty"));
    }

    Ok(row)
}

fn main() -> Result<(), io::Error> {
    let row0 = pascals_triangle_row(0)?;
    println!("Row 0: {:?}", row0);

    let row3 = pascals_triangle_row(3)?;
    println!("Row 3: {:?}", row3);

    let row_max = pascals_triangle_row(60)?;
    println!("Row 60 first element: {}", row_max[0]);
    println!("Row 60 last element: {}", row_max[row_max.len() - 1]);

    // Example of error propagation
    let _ = pascals_triangle_row(u32::MAX)?; // This will likely overflow or take forever

    Ok(())
}

